import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";

/**
 * Test successful guest user registration with valid session tracking data.
 *
 * This test validates that anonymous users can create temporary guest accounts
 * by providing required connection metadata (IP address, current page URL, and
 * referrer URL). The test verifies that the system creates a new guest record
 * in the discussion_board_guests table, generates a unique UUID identifier, and
 * issues both access and refresh JWT tokens.
 *
 * Steps:
 *
 * 1. Generate valid guest registration request data with IP, href, and referrer
 * 2. Call the guest registration API endpoint
 * 3. Validate that the response structure matches
 *    IDiscussionBoardGuest.IAuthorized
 */
export async function test_api_guest_registration_success(
  connection: api.IConnection,
) {
  // Step 1: Generate valid guest registration request data
  const requestBody = {
    ip: typia.random<string>(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardGuest.ICreate;

  // Step 2: Call the guest registration API endpoint
  const guestAuthorized: IDiscussionBoardGuest.IAuthorized =
    await api.functional.auth.guest.join(connection, {
      body: requestBody,
    });

  // Step 3: Validate the complete response structure
  // This validates EVERYTHING: UUID format, date-time formats, all types and constraints
  typia.assert(guestAuthorized);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";

/**
 * Test guest registration using IPv4 address format for session tracking.
 *
 * This test validates that the system correctly accepts and stores IPv4
 * addresses in the standard dotted decimal notation (e.g., 192.168.1.1). The
 * test verifies that the IP address is properly recorded in the guest session
 * record for audit trails and security monitoring, and confirms successful
 * account creation and token issuance with IPv4 format.
 *
 * Steps:
 *
 * 1. Generate a valid IPv4 address in dotted decimal notation
 * 2. Create valid URI strings for href and referrer fields
 * 3. Call the guest registration API endpoint
 * 4. Validate the complete response structure with typia.assert
 */
export async function test_api_guest_registration_with_valid_ipv4(
  connection: api.IConnection,
) {
  const ipv4 = `${typia.random<number & tags.Type<"uint32"> & tags.Minimum<1> & tags.Maximum<255>>()}.${typia.random<number & tags.Type<"uint32"> & tags.Minimum<0> & tags.Maximum<255>>()}.${typia.random<number & tags.Type<"uint32"> & tags.Minimum<0> & tags.Maximum<255>>()}.${typia.random<number & tags.Type<"uint32"> & tags.Minimum<1> & tags.Maximum<255>>()}`;

  const requestBody = {
    ip: ipv4,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardGuest.ICreate;

  const response: IDiscussionBoardGuest.IAuthorized =
    await api.functional.auth.guest.join(connection, {
      body: requestBody,
    });

  typia.assert(response);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";

/**
 * Test guest registration using IPv6 address format for session tracking.
 *
 * This test validates that the system correctly accepts and stores IPv6
 * addresses in standard notation (e.g.,
 * 2001:0db8:85a3:0000:0000:8a2e:0370:7334).
 *
 * Verify that modern IPv6 addresses are properly handled and stored in the
 * guest session record. Confirm successful account creation and token issuance
 * with IPv6 format.
 *
 * Steps:
 *
 * 1. Generate a valid IPv6 address in standard notation
 * 2. Create valid URI values for href and referrer
 * 3. Register a guest user with the IPv6 address
 * 4. Validate the response contains guest ID and tokens
 */
export async function test_api_guest_registration_with_valid_ipv6(
  connection: api.IConnection,
) {
  const ipv6Address = "2001:0db8:85a3:0000:0000:8a2e:0370:7334";

  const guestCreateData = {
    ip: ipv6Address,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardGuest.ICreate;

  const guest = await api.functional.auth.guest.join(connection, {
    body: guestCreateData,
  });

  typia.assert(guest);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";

/**
 * Test guest registration with empty referrer for direct access scenarios.
 *
 * This test validates that the system correctly handles guest registration when
 * users access the site directly without a referrer (e.g., typing URL directly,
 * bookmarks, or external applications). The referrer field is required but can
 * be an empty string for direct access cases.
 *
 * Test Flow:
 *
 * 1. Prepare guest registration data with empty referrer string
 * 2. Call guest registration API with valid IP and href but empty referrer
 * 3. Validate response structure and token issuance
 * 4. Verify guest account is created with proper JWT tokens
 */
export async function test_api_guest_registration_with_empty_referrer(
  connection: api.IConnection,
) {
  // Generate valid IP address (simulating client connection)
  const clientIp = `${typia.random<number & tags.Type<"uint32"> & tags.Minimum<1> & tags.Maximum<255>>()}.${typia.random<number & tags.Type<"uint32"> & tags.Minimum<0> & tags.Maximum<255>>()}.${typia.random<number & tags.Type<"uint32"> & tags.Minimum<0> & tags.Maximum<255>>()}.${typia.random<number & tags.Type<"uint32"> & tags.Minimum<1> & tags.Maximum<254>>()}`;

  // Create guest registration request with empty referrer
  const guestRegistrationData = {
    ip: clientIp,
