/**
 * Test that moderator login properly captures and stores session metadata.
 *
 * This test validates that the authentication system correctly collects session
 * context information including IP address, connection URL (href), and referrer
 * during the login process. This metadata is essential for security audit
 * trails, suspicious activity detection, and user flow analysis.
 *
 * Test workflow:
 *
 * 1. Create a moderator account with initial session metadata
 * 2. Login with explicit session context fields (ip, href, referrer)
 * 3. Validate successful authentication with proper token response
 * 4. Ensure session metadata is captured during the login process
 */
export async function test_api_moderator_login_session_metadata_capture(
  connection: api.IConnection,
) {
  // Step 1: Generate moderator credentials and session metadata
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "SecurePass123!";
  const moderatorUsername = RandomGenerator.name(2);

  const sessionIp = "192.168.1.100";
  const sessionHref = typia.random<string & tags.Format<"uri">>();
  const sessionReferrer = typia.random<string & tags.Format<"uri">>();

  // Step 2: Create moderator account with join endpoint
  const joinedModerator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        email: moderatorEmail,
        password: moderatorPassword,
        username: moderatorUsername,
        ip: sessionIp,
        href: sessionHref,
        referrer: sessionReferrer,
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(joinedModerator);

  // Validate join response contains expected moderator information
  TestValidator.equals(
    "joined moderator email matches",
    joinedModerator.email,
    moderatorEmail,
  );
  TestValidator.equals(
    "joined moderator username matches",
    joinedModerator.username,
    moderatorUsername,
  );

  // Step 3: Login with explicit session metadata
  const loginSessionIp = "10.0.0.50";
  const loginSessionHref = typia.random<string & tags.Format<"uri">>();
  const loginSessionReferrer = typia.random<string & tags.Format<"uri">>();

  const loggedInModerator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.login(connection, {
      body: {
        email: moderatorEmail,
        password: moderatorPassword,
        ip: loginSessionIp,
        href: loginSessionHref,
        referrer: loginSessionReferrer,
      } satisfies IDiscussionBoardModerator.ILogin,
    });
  typia.assert(loggedInModerator);

  // Step 4: Validate login response and session metadata capture
  TestValidator.equals(
    "logged in moderator ID matches",
    loggedInModerator.id,
    joinedModerator.id,
  );
  TestValidator.equals(
    "logged in moderator email matches",
    loggedInModerator.email,
    moderatorEmail,
  );
  TestValidator.equals(
    "logged in moderator username matches",
    loggedInModerator.username,
    moderatorUsername,
  );

  // Validate authorization tokens are present
  TestValidator.predicate(
    "access token is present",
    loggedInModerator.token.access.length > 0,
  );
  TestValidator.predicate(
    "refresh token is present",
    loggedInModerator.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "token expiration is set",
    loggedInModerator.token.expired_at.length > 0,
  );
  TestValidator.predicate(
    "refresh expiration is set",
    loggedInModerator.token.refreshable_until.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test successful token refresh using a valid refresh token.
 *
 * This test validates the complete token refresh workflow including refresh
 * token validation, session verification, and new token generation. Create a
 * moderator account, perform initial login to obtain tokens, then use the
 * refresh token to get new access tokens. Verify that the refresh operation
 * returns new valid JWT tokens with updated expiration timestamps while
 * maintaining the moderator's authenticated session.
 *
 * **Test Steps:**
 *
 * 1. Create a new moderator account with valid credentials
 * 2. Verify initial authentication returns complete token set
 * 3. Extract and validate the refresh token from initial authentication
 * 4. Use refresh token to obtain new access tokens
 * 5. Verify new tokens are valid and have updated expiration timestamps
 * 6. Ensure moderator session remains active after token refresh
 */
export async function test_api_moderator_refresh_token_successful_renewal(
  connection: api.IConnection,
) {
  // Step 1: Create a new moderator account
  const createData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "SecurePassword123!",
    username: RandomGenerator.name(1),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardModerator.ICreate;

  const initialAuth: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: createData,
    });
  typia.assert(initialAuth);

  // Step 2: Verify initial authentication response
  typia.assert(initialAuth.token);
  TestValidator.predicate(
    "initial auth contains access token",
    initialAuth.token.access.length > 0,
  );
  TestValidator.predicate(
    "initial auth contains refresh token",
    initialAuth.token.refresh.length > 0,
  );

  // Step 3: Store the initial refresh token for comparison
  const initialRefreshToken = initialAuth.token.refresh;
  const initialExpiredAt = new Date(initialAuth.token.expired_at);
  const initialRefreshableUntil = new Date(initialAuth.token.refreshable_until);

  // Step 4: Use the refresh token to obtain new access tokens
  const refreshData = {
    refresh_token: initialRefreshToken,
  } satisfies IDiscussionBoardModerator.IRefresh;

  const refreshedAuth: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.refresh(connection, {
      body: refreshData,
    });
  typia.assert(refreshedAuth);

  // Step 5: Verify the refresh operation returned valid new tokens
  typia.assert(refreshedAuth.token);
  TestValidator.predicate(
    "refreshed auth contains new access token",
    refreshedAuth.token.access.length > 0,
  );
  TestValidator.predicate(
    "refreshed auth contains refresh token",
    refreshedAuth.token.refresh.length > 0,
  );

  // Step 6: Verify moderator identity is preserved
  TestValidator.equals(
    "moderator ID remains unchanged",
    refreshedAuth.id,
    initialAuth.id,
  );
  TestValidator.equals(
    "moderator username remains unchanged",
    refreshedAuth.username,
    initialAuth.username,
  );
  TestValidator.equals(
    "moderator email remains unchanged",
    refreshedAuth.email,
    initialAuth.email,
  );

  // Step 7: Verify token expiration timestamps are valid
  const refreshedExpiredAt = new Date(refreshedAuth.token.expired_at);
  const refreshedRefreshableUntil = new Date(
    refreshedAuth.token.refreshable_until,
  );

  TestValidator.predicate(
    "refreshed access token has valid expiration",
    refreshedExpiredAt.getTime() > Date.now(),
  );
  TestValidator.predicate(
    "refresh token has valid refreshable_until",
    refreshedRefreshableUntil.getTime() > Date.now(),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test token refresh attempt with an invalid or malformed refresh token.
 *
 * This test validates that the system properly rejects refresh attempts when
 * the provided token is not a valid JWT, has an invalid signature, or is
 * otherwise malformed. It verifies appropriate error handling, security
 * measures to prevent token forgery, and that no new tokens are issued.
 *
 * The test ensures the system validates token structure and cryptographic
 * signature before processing the refresh request, which is critical for
 * maintaining authentication security and preventing unauthorized access.
 *
 * Steps:
 *
 * 1. Generate an invalid/malformed refresh token (not a valid JWT)
 * 2. Attempt to refresh tokens using the invalid token
 * 3. Verify that the API properly rejects the request with an error
 * 4. Confirm that no authentication tokens are issued for invalid requests
 */
export async function test_api_moderator_refresh_token_invalid_token(
  connection: api.IConnection,
) {
  // Test with a completely invalid token (random string)
  const invalidToken = RandomGenerator.alphaNumeric(32);

  await TestValidator.error(
    "refresh should fail with invalid token",
    async () => {
      await api.functional.auth.moderator.refresh(connection, {
        body: {
          refresh_token: invalidToken,
        } satisfies IDiscussionBoardModerator.IRefresh,
      });
    },
  );

  // Test with malformed JWT-like structure (invalid format)
  const malformedToken = `${RandomGenerator.alphaNumeric(10)}.${RandomGenerator.alphaNumeric(10)}.invalid_signature`;

  await TestValidator.error(
    "refresh should fail with malformed JWT token",
    async () => {
      await api.functional.auth.moderator.refresh(connection, {
        body: {
          refresh_token: malformedToken,
        } satisfies IDiscussionBoardModerator.IRefresh,
      });
    },
  );

  // Test with empty string token
  await TestValidator.error(
    "refresh should fail with empty token",
    async () => {
      await api.functional.auth.moderator.refresh(connection, {
        body: {
          refresh_token: "",
        } satisfies IDiscussionBoardModerator.IRefresh,
      });
    },
  );
}

