import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test token rotation mechanism where each refresh issues completely new tokens
 * and may invalidate old refresh tokens.
 *
 * This test validates security best practices for token refresh by ensuring
 * that refresh tokens can only be used once (if rotation is implemented). The
 * test workflow:
 *
 * 1. Create a moderator account via join endpoint
 * 2. Login to obtain initial access and refresh tokens
 * 3. Perform first token refresh using the refresh token
 * 4. Attempt to reuse the old refresh token (should fail if rotation is
 *    implemented)
 *
 * The test verifies that the system implements appropriate rotation policies to
 * enhance security against token theft.
 */
export async function test_api_moderator_refresh_token_rotation(
  connection: api.IConnection,
) {
  // Step 1: Create a moderator account
  const createData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    username: RandomGenerator.name(1),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardModerator.ICreate;

  const createdModerator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: createData,
    });
  typia.assert(createdModerator);

  // Step 2: Login to get initial tokens (using fresh connection to avoid auto-token management)
  const freshConnection: api.IConnection = { ...connection, headers: {} };
  const loginData = {
    email: createData.email,
    password: createData.password,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardModerator.ILogin;

  const loginResult: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.login(freshConnection, {
      body: loginData,
    });
  typia.assert(loginResult);

  const initialRefreshToken: string = loginResult.token.refresh;

  // Step 3: Perform first token refresh
  const firstRefreshData = {
    refresh_token: initialRefreshToken,
  } satisfies IDiscussionBoardModerator.IRefresh;

  const firstRefreshResult: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.refresh(freshConnection, {
      body: firstRefreshData,
    });
  typia.assert(firstRefreshResult);

  // Verify new tokens were issued
  TestValidator.predicate(
    "new access token should be different from initial",
    firstRefreshResult.token.access !== loginResult.token.access,
  );

  // Step 4: Attempt to reuse the old refresh token (should fail if rotation is implemented)
  await TestValidator.error(
    "old refresh token should be invalidated after rotation",
    async () => {
      await api.functional.auth.moderator.refresh(freshConnection, {
        body: {
          refresh_token: initialRefreshToken,
        } satisfies IDiscussionBoardModerator.IRefresh,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Test the complete workflow of a member updating their own comment on an
 * article.
 *
 * This test validates that authenticated members can successfully modify
 * comments they have authored. The workflow includes:
 *
 * 1. Member registration and authentication
 * 2. Article creation for comment context
 * 3. Initial comment creation
 * 4. Comment content update
 * 5. Validation of updated content and metadata preservation
 *
 * The test ensures proper ownership validation, content persistence, timestamp
 * updates, and referential integrity throughout the update operation.
 */
export async function test_api_comment_update_by_author(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate a member account
  const memberData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "SecurePassword123!",
    username: RandomGenerator.name(2),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMember.ICreate;

  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: memberData,
    });
  typia.assert(member);

  // Step 2: Create a discussion board article
  const articleData = {
    title: RandomGenerator.paragraph({ sentences: 3, wordMin: 3, wordMax: 8 }),
    body: RandomGenerator.content({
      paragraphs: 3,
      sentenceMin: 10,
      sentenceMax: 20,
    }),
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.articles.create(connection, {
      body: articleData,
    });
  typia.assert(article);

  // Step 3: Post an initial comment on the article
  const originalCommentContent = RandomGenerator.paragraph({
    sentences: 10,
    wordMin: 4,
    wordMax: 10,
  });

  const commentData = {
    content: originalCommentContent,
  } satisfies IDiscussionBoardComment.ICreate;

  const createdComment: IDiscussionBoardComment =
    await api.functional.discussionBoard.member.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: commentData,
      },
    );
  typia.assert(createdComment);

  // Validate initial comment creation
  TestValidator.equals(
    "initial comment content matches",
    createdComment.content,
    originalCommentContent,
  );
  TestValidator.equals(
    "comment belongs to correct article",
    createdComment.discussion_board_article_id,
    article.id,
  );
  TestValidator.equals(
    "comment authored by correct member",
    createdComment.member_id,
    member.id,
  );

  // Step 4: Update the comment with new content
  const updatedCommentContent = RandomGenerator.paragraph({
    sentences: 12,
    wordMin: 5,
    wordMax: 9,
  });

  const updateData = {
    content: updatedCommentContent,
  } satisfies IDiscussionBoardComment.IUpdate;

  const updatedComment: IDiscussionBoardComment =
    await api.functional.discussionBoard.member.articles.comments.update(
      connection,
      {
        articleId: article.id,
        commentId: createdComment.id,
        body: updateData,
      },
    );
  typia.assert(updatedComment);

  // Step 5: Validate the update was successful
  TestValidator.equals(
    "updated comment content is correct",
    updatedComment.content,
    updatedCommentContent,
  );
  TestValidator.notEquals(
    "content has changed from original",
    updatedComment.content,
    originalCommentContent,
  );

  // Validate metadata preservation
  TestValidator.equals(
    "comment ID unchanged",
    updatedComment.id,
    createdComment.id,
  );
  TestValidator.equals(
    "article relationship preserved",
    updatedComment.discussion_board_article_id,
    article.id,
  );
  TestValidator.equals(
    "member ownership preserved",
    updatedComment.member_id,
    member.id,
  );
  TestValidator.equals(
    "created_at timestamp unchanged",
    updatedComment.created_at,
    createdComment.created_at,
  );

  // Validate that updated_at has been modified
  TestValidator.predicate(
    "updated_at timestamp is later than created_at",
    new Date(updatedComment.updated_at) >= new Date(updatedComment.created_at),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
