  // Step 2: Member creates an article for discussion
  const articleCreateData = {
    title: "Economic Analysis: Impact of Monetary Policy on Inflation",
    body: RandomGenerator.content({
      paragraphs: 3,
      sentenceMin: 10,
      sentenceMax: 20,
      wordMin: 4,
      wordMax: 8,
    }),
