import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test moderator's ability to perform partial updates on articles.
 *
 * This test validates that moderators can update individual fields of an
 * article without affecting other fields. It verifies:
 *
 * 1. Member creates an article with initial title and body
 * 2. Moderator updates only the title field
 * 3. Body remains unchanged after title update
 * 4. Moderator updates only the body field
 * 5. Title (from previous update) remains unchanged after body update
 * 6. Each update refreshes the updated_at timestamp
 */
export async function test_api_article_moderator_partial_update(
  connection: api.IConnection,
) {
  // Step 1: Create member account and authenticate
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "member_password_123";

  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      username: RandomGenerator.name(),
      ip: "127.0.0.1",
      href: "https://example.com/join" satisfies string & tags.Format<"uri">,
      referrer: "" satisfies string & tags.Format<"uri">,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Step 2: Member creates article with specific initial content
  const initialTitle = RandomGenerator.paragraph({
    sentences: 3,
    wordMin: 5,
    wordMax: 10,
  });
  const initialBody = RandomGenerator.content({
    paragraphs: 2,
    sentenceMin: 10,
    sentenceMax: 15,
  });

  const createdArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: {
        title: initialTitle,
        body: initialBody,
      } satisfies IDiscussionBoardArticle.ICreate,
    });
  typia.assert(createdArticle);

  TestValidator.equals(
    "initial article title matches",
    createdArticle.title,
    initialTitle,
  );
  TestValidator.equals(
    "initial article body matches",
    createdArticle.body,
    initialBody,
  );

  // Step 3: Create moderator account and authenticate
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "moderator_password_123";

  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      username: RandomGenerator.name(),
      ip: "127.0.0.1",
      href: "https://example.com/moderator/join" satisfies string &
        tags.Format<"uri">,
      referrer: "" satisfies string & tags.Format<"uri">,
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 4: Moderator updates only the title field
  const updatedTitle = RandomGenerator.paragraph({
    sentences: 4,
    wordMin: 6,
    wordMax: 12,
  });

  const afterTitleUpdate =
    await api.functional.discussionBoard.moderator.articles.update(connection, {
      articleId: createdArticle.id,
      body: {
        title: updatedTitle,
      } satisfies IDiscussionBoardArticle.IUpdate,
    });
  typia.assert(afterTitleUpdate);

  // Step 5: Verify title is updated while body remains unchanged
  TestValidator.equals(
    "title is updated",
    afterTitleUpdate.title,
    updatedTitle,
  );
  TestValidator.equals(
    "body remains unchanged after title update",
    afterTitleUpdate.body,
    initialBody,
  );
  TestValidator.predicate(
    "updated_at is refreshed after title update",
    new Date(afterTitleUpdate.updated_at).getTime() >
      new Date(createdArticle.updated_at).getTime(),
  );

  // Step 6: Moderator updates only the body field in a second update
  const updatedBody = RandomGenerator.content({
    paragraphs: 3,
    sentenceMin: 8,
    sentenceMax: 12,
  });

  const afterBodyUpdate =
    await api.functional.discussionBoard.moderator.articles.update(connection, {
      articleId: createdArticle.id,
      body: {
        body: updatedBody,
      } satisfies IDiscussionBoardArticle.IUpdate,
    });
  typia.assert(afterBodyUpdate);

  // Step 7: Verify body is updated while title remains from previous update
  TestValidator.equals("body is updated", afterBodyUpdate.body, updatedBody);
  TestValidator.equals(
    "title remains from previous update",
    afterBodyUpdate.title,
    updatedTitle,
  );
  TestValidator.predicate(
    "updated_at is refreshed after body update",
    new Date(afterBodyUpdate.updated_at).getTime() >
      new Date(afterTitleUpdate.updated_at).getTime(),
  );

  // Final verification: ensure all changes are reflected correctly
  TestValidator.notEquals(
    "final title differs from initial",
    afterBodyUpdate.title,
    initialTitle,
  );
  TestValidator.notEquals(
    "final body differs from initial",
    afterBodyUpdate.body,
    initialBody,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test that moderator article updates enforce content validation constraints.
 *
 * This test validates that even moderators cannot bypass content validation
 * rules when updating articles. It ensures data quality is maintained through
 * proper title and body length constraints regardless of user role.
 *
 * Workflow:
 *
 * 1. Create member account and authenticate
 * 2. Member creates a valid article
 * 3. Create moderator account and authenticate
 * 4. Test title validation with too short title (< 5 chars) - should fail
 * 5. Test title validation with too long title (> 200 chars) - should fail
 * 6. Test body validation with too short body (< 10 chars) - should fail
 * 7. Test body validation with too long body (> 50,000 chars) - should fail
 * 8. Perform valid update with proper constraints - should succeed
 * 9. Verify successful update
 */
export async function test_api_article_moderator_update_validation(
  connection: api.IConnection,
) {
  // Step 1: Create member account
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "member_password_123";
  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      username: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Step 2: Member creates a valid article
  const article = await api.functional.discussionBoard.member.articles.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 3,
          wordMin: 3,
          wordMax: 7,
        }),
        body: RandomGenerator.content({
          paragraphs: 3,
          sentenceMin: 10,
          sentenceMax: 20,
          wordMin: 4,
          wordMax: 8,
        }),
      } satisfies IDiscussionBoardArticle.ICreate,
    },
  );
  typia.assert(article);

  // Step 3: Create moderator account and authenticate
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "moderator_password_123";
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      username: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 4: Test title too short (< 5 characters) - should fail
  await TestValidator.error(
    "title below minimum length should fail",
    async () => {
      await api.functional.discussionBoard.moderator.articles.update(
        connection,
        {
          articleId: article.id,
          body: {
            title: RandomGenerator.alphabets(3),
          } satisfies IDiscussionBoardArticle.IUpdate,
        },
      );
    },
  );

  // Step 5: Test title too long (> 200 characters) - should fail
  await TestValidator.error(
    "title exceeding maximum length should fail",
    async () => {
      await api.functional.discussionBoard.moderator.articles.update(
        connection,
        {
          articleId: article.id,
          body: {
            title: RandomGenerator.alphabets(201),
          } satisfies IDiscussionBoardArticle.IUpdate,
        },
      );
    },
  );

  // Step 6: Test body too short (< 10 characters) - should fail
  await TestValidator.error(
    "body below minimum length should fail",
    async () => {
      await api.functional.discussionBoard.moderator.articles.update(
        connection,
        {
          articleId: article.id,
          body: {
            body: RandomGenerator.alphabets(5),
          } satisfies IDiscussionBoardArticle.IUpdate,
        },
      );
    },
  );

  // Step 7: Test body too long (> 50,000 characters) - should fail
  await TestValidator.error(
    "body exceeding maximum length should fail",
    async () => {
      await api.functional.discussionBoard.moderator.articles.update(
        connection,
        {
          articleId: article.id,
          body: {
            body: RandomGenerator.alphabets(50001),
          } satisfies IDiscussionBoardArticle.IUpdate,
        },
      );
    },
  );

  // Step 8: Perform valid update with proper constraints
  const validTitle = RandomGenerator.paragraph({
    sentences: 5,
    wordMin: 3,
    wordMax: 7,
  });
  const validBody = RandomGenerator.content({
    paragraphs: 5,
    sentenceMin: 15,
    sentenceMax: 25,
    wordMin: 4,
    wordMax: 8,
  });
  const updatedArticle =
    await api.functional.discussionBoard.moderator.articles.update(connection, {
      articleId: article.id,
      body: {
        title: validTitle,
        body: validBody,
      } satisfies IDiscussionBoardArticle.IUpdate,
    });
  typia.assert(updatedArticle);

  // Step 9: Verify successful update
  TestValidator.equals(
    "updated title matches",
    updatedArticle.title,
    validTitle,
  );
  TestValidator.equals("updated body matches", updatedArticle.body, validBody);
  TestValidator.equals("article ID unchanged", updatedArticle.id, article.id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Test that a member can successfully update their own article content.
 *
 * This test validates ownership-based authorization by ensuring members can
 * modify articles they created. It verifies that content fields (title, body)
 * are updateable while system fields remain protected. The test confirms that
 * updated_at timestamp is refreshed while created_at remains immutable, and
 * that author information and system metadata stay unchanged.
 *
 * Workflow:
 *
 * 1. Create and authenticate member account
 * 2. Member creates initial article with title and body
 * 3. Same member updates the article with new content
 * 4. Verify article content is updated correctly
 * 5. Verify updated_at timestamp is refreshed
 * 6. Verify created_at timestamp remains unchanged
 * 7. Verify author information remains the same
 * 8. Verify system metadata (id, view_count) is unchanged
 */
export async function test_api_article_member_update_own_content(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate member account
  const memberData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "securePassword123",
    username: RandomGenerator.name(2),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMember.ICreate;

  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: memberData,
    });
  typia.assert(member);

  // Step 2: Member creates initial article
  const initialTitle = RandomGenerator.paragraph({
    sentences: 3,
    wordMin: 3,
    wordMax: 7,
  });
  const initialBody = RandomGenerator.content({
    paragraphs: 3,
    sentenceMin: 10,
    sentenceMax: 20,
    wordMin: 4,
    wordMax: 8,
  });

  const initialArticleData = {
    title: initialTitle,
    body: initialBody,
  } satisfies IDiscussionBoardArticle.ICreate;

  const createdArticle: IDiscussionBoardArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: initialArticleData,
    });
  typia.assert(createdArticle);

  // Capture original values for comparison
  const originalCreatedAt = createdArticle.created_at;
  const originalUpdatedAt = createdArticle.updated_at;
  const originalAuthorId = createdArticle.author.id;
  const originalArticleId = createdArticle.id;
  const originalViewCount = createdArticle.view_count;

  // Wait a brief moment to ensure timestamp difference
  await new Promise((resolve) => setTimeout(resolve, 100));

  // Step 3: Update the article with new content
  const updatedTitle = RandomGenerator.paragraph({
    sentences: 4,
    wordMin: 4,
    wordMax: 8,
  });
  const updatedBody = RandomGenerator.content({
    paragraphs: 4,
    sentenceMin: 15,
    sentenceMax: 25,
    wordMin: 5,
    wordMax: 9,
  });

  const updateData = {
    title: updatedTitle,
    body: updatedBody,
  } satisfies IDiscussionBoardArticle.IUpdate;

  const updatedArticle: IDiscussionBoardArticle =
    await api.functional.discussionBoard.articles.update(connection, {
      articleId: createdArticle.id,
      body: updateData,
    });
  typia.assert(updatedArticle);

  // Step 4: Verify article content is updated correctly
  TestValidator.equals(
    "updated title matches new value",
    updatedArticle.title,
    updatedTitle,
  );
  TestValidator.equals(
    "updated body matches new value",
    updatedArticle.body,
    updatedBody,
  );

  // Step 5: Verify updated_at timestamp is refreshed
  TestValidator.predicate(
    "updated_at timestamp is refreshed after update",
    new Date(updatedArticle.updated_at).getTime() >
      new Date(originalUpdatedAt).getTime(),
  );

  // Step 6: Verify created_at timestamp remains unchanged (immutable)
  TestValidator.equals(
    "created_at remains unchanged",
    updatedArticle.created_at,
    originalCreatedAt,
  );

  // Step 7: Verify author information remains the same
  TestValidator.equals(
    "author ID remains unchanged",
    updatedArticle.author.id,
    originalAuthorId,
  );
  TestValidator.equals(
    "author is the member who created article",
    updatedArticle.author.id,
    member.id,
  );

  // Step 8: Verify system metadata (id, view_count) remains unchanged
  TestValidator.equals(
    "article ID remains unchanged",
    updatedArticle.id,
    originalArticleId,
  );
  TestValidator.equals(
    "view count remains unchanged",
    updatedArticle.view_count,
    originalViewCount,
  );

  // Verify content constraints are met
  TestValidator.predicate(
    "title length is within 5-200 constraint",
    updatedArticle.title.length >= 5 && updatedArticle.title.length <= 200,
  );
  TestValidator.predicate(
    "body length is within 10-50000 constraint",
    updatedArticle.body.length >= 10 && updatedArticle.body.length <= 50000,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Test that authorization properly prevents members from updating articles
 * created by other members, enforcing ownership boundaries.
 *
 * This test validates the critical authorization boundary that ensures members
 * can only update their own articles. It verifies that attempts by non-owners
 * to update articles are properly rejected, while the original author retains
 * full update privileges.
 *
 * Workflow steps:
 *
 * 1. Create first member account (author) and authenticate
 * 2. First member creates an article
 * 3. Create second member account (non-author) and authenticate
 * 4. Second member attempts to update the article created by first member
 * 5. Verify update is rejected with authorization error
 * 6. Confirm article content remains unchanged
 * 7. First member (original author) successfully updates the article
 * 8. Verify update succeeds for the owner
 */
export async function test_api_article_member_update_authorization_enforcement(
  connection: api.IConnection,
) {
  // Step 1: Create first member account (author) and authenticate
  const firstMemberEmail = typia.random<string & tags.Format<"email">>();
  const firstMemberPassword = "password123";
  const firstMember: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: {
        email: firstMemberEmail,
        password: firstMemberPassword,
        username: RandomGenerator.name(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(firstMember);

  // Store first member's token for later use
  const firstMemberToken = firstMember.token.access;

  // Step 2: First member creates an article
  const originalTitle = RandomGenerator.paragraph({
    sentences: 3,
    wordMin: 5,
    wordMax: 10,
  });
  const originalBody = RandomGenerator.content({
    paragraphs: 2,
    sentenceMin: 10,
    sentenceMax: 15,
  });

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: {
        title: originalTitle,
        body: originalBody,
      } satisfies IDiscussionBoardArticle.ICreate,
    });
  typia.assert(article);
  TestValidator.equals("article title matches", article.title, originalTitle);
  TestValidator.equals("article body matches", article.body, originalBody);
  TestValidator.equals(
    "article author is first member",
    article.author.id,
    firstMember.id,
  );

  // Step 3: Create second member account (non-author) and authenticate
  const secondMemberEmail = typia.random<string & tags.Format<"email">>();
  const secondMemberPassword = "password456";
  const secondMember: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: {
        email: secondMemberEmail,
        password: secondMemberPassword,
        username: RandomGenerator.name(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(secondMember);

  // Step 4: Second member attempts to update the article created by first member
  const unauthorizedUpdateTitle = RandomGenerator.paragraph({
    sentences: 3,
    wordMin: 5,
    wordMax: 10,
  });
  const unauthorizedUpdateBody = RandomGenerator.content({
    paragraphs: 2,
    sentenceMin: 10,
    sentenceMax: 15,
  });

  await TestValidator.error(
    "second member cannot update first member's article",
    async () => {
      await api.functional.discussionBoard.articles.update(connection, {
        articleId: article.id,
        body: {
          title: unauthorizedUpdateTitle,
          body: unauthorizedUpdateBody,
        } satisfies IDiscussionBoardArticle.IUpdate,
      });
    },
  );

  // Step 7: Switch back to first member (original author) for successful update
  connection.headers = connection.headers || {};
  connection.headers.Authorization = firstMemberToken;

  // Step 8: First member (original author) successfully updates the article
  const authorizedUpdateTitle = RandomGenerator.paragraph({
    sentences: 3,
    wordMin: 5,
    wordMax: 10,
  });
  const authorizedUpdateBody = RandomGenerator.content({
    paragraphs: 2,
    sentenceMin: 10,
    sentenceMax: 15,
  });

  const updatedArticle: IDiscussionBoardArticle =
    await api.functional.discussionBoard.articles.update(connection, {
      articleId: article.id,
      body: {
        title: authorizedUpdateTitle,
        body: authorizedUpdateBody,
      } satisfies IDiscussionBoardArticle.IUpdate,
    });
  typia.assert(updatedArticle);

  // Verify update succeeds for the owner
  TestValidator.equals(
    "updated article title matches",
    updatedArticle.title,
    authorizedUpdateTitle,
  );
  TestValidator.equals(
    "updated article body matches",
    updatedArticle.body,
    authorizedUpdateBody,
  );
  TestValidator.equals(
    "article ID remains same",
    updatedArticle.id,
    article.id,
  );
  TestValidator.equals(
    "article author remains same",
    updatedArticle.author.id,
    firstMember.id,
  );
  TestValidator.notEquals(
    "article title changed from original",
    updatedArticle.title,
    originalTitle,
  );
  TestValidator.notEquals(
    "article body changed from original",
    updatedArticle.body,
    originalBody,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Test member's ability to update individual fields of their article without
 * affecting other fields.
 *
 * This test validates the partial update functionality ensuring that when
 * updating only the title, the body remains unchanged, and when updating only
 * the body, the title remains unchanged. It also verifies that the updated_at
 * timestamp changes with each update.
 *
 * Workflow:
 *
 * 1. Create and authenticate member account
 * 2. Create article with specific initial title and body
 * 3. Update only title field, verify body unchanged
 * 4. Update only body field, verify title unchanged
 * 5. Verify updated_at timestamp progresses correctly
 * 6. Ensure no unintended side effects on other fields
 */
export async function test_api_article_member_partial_field_update(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate member account
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "TestPassword123!";
  const memberUsername = RandomGenerator.name();

  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      username: memberUsername,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Step 2: Create article with known initial title and body
  const originalTitle = RandomGenerator.paragraph({
    sentences: 3,
    wordMin: 5,
    wordMax: 10,
  });
  const originalBody = RandomGenerator.content({
    paragraphs: 2,
    sentenceMin: 10,
    sentenceMax: 15,
  });

  const createdArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: {
        title: originalTitle,
        body: originalBody,
      } satisfies IDiscussionBoardArticle.ICreate,
    });
  typia.assert(createdArticle);

  TestValidator.equals(
    "created article title matches",
    createdArticle.title,
    originalTitle,
  );
  TestValidator.equals(
    "created article body matches",
    createdArticle.body,
    originalBody,
  );

  const originalCreatedAt = createdArticle.created_at;
  const firstUpdatedAt = createdArticle.updated_at;

  // Step 3: Update only the title field, body should remain unchanged
  const newTitle = RandomGenerator.paragraph({
    sentences: 4,
    wordMin: 4,
    wordMax: 8,
  });

  const titleUpdatedArticle =
    await api.functional.discussionBoard.articles.update(connection, {
      articleId: createdArticle.id,
      body: {
        title: newTitle,
      } satisfies IDiscussionBoardArticle.IUpdate,
    });
  typia.assert(titleUpdatedArticle);

  TestValidator.equals(
    "title updated successfully",
    titleUpdatedArticle.title,
    newTitle,
  );
  TestValidator.equals(
    "body remained unchanged after title update",
    titleUpdatedArticle.body,
    originalBody,
  );
  TestValidator.equals(
    "article ID remained stable",
    titleUpdatedArticle.id,
    createdArticle.id,
  );
  TestValidator.equals(
    "created_at timestamp unchanged",
    titleUpdatedArticle.created_at,
    originalCreatedAt,
  );
  TestValidator.predicate(
    "updated_at changed after title update",
    titleUpdatedArticle.updated_at !== firstUpdatedAt,
  );

  const secondUpdatedAt = titleUpdatedArticle.updated_at;

  // Step 4: Update only the body field, title should remain from previous update
  const newBody = RandomGenerator.content({
    paragraphs: 3,
    sentenceMin: 12,
    sentenceMax: 20,
  });

  const bodyUpdatedArticle =
    await api.functional.discussionBoard.articles.update(connection, {
      articleId: createdArticle.id,
      body: {
        body: newBody,
      } satisfies IDiscussionBoardArticle.IUpdate,
    });
  typia.assert(bodyUpdatedArticle);

  TestValidator.equals(
    "body updated successfully",
    bodyUpdatedArticle.body,
    newBody,
  );
  TestValidator.equals(
    "title remained from previous update",
    bodyUpdatedArticle.title,
    newTitle,
  );
  TestValidator.equals(
    "article ID still stable",
