  TestValidator.equals(
    "medium file size matches expected",
    mediumFile.file_size,
    mediumFileSize,
  );

  // Step 5: Attach a large file approaching the 25 MB limit (24 MB = 24 * 1024 * 1024 bytes)
  const largeFileSize = 24 * 1024 * 1024;
