/**
 * Test filtering articles by specific author (member ID) to retrieve all
 * articles written by a particular discussion board member.
 *
 * This test validates the discussion_board_member_id filtering capability by:
 *
 * 1. Creating two different member accounts (Member A and Member B)
 * 2. Having each member publish several articles
 * 3. Filtering by Member A's ID to verify only their articles are returned
 * 4. Ensuring filtered results maintain proper pagination
 * 5. Verifying correct author information is included in article summaries
 *
 * This functionality is essential for member profile pages and browsing all
 * contributions from a specific author on the discussion board.
 */
export async function test_api_article_filter_by_author(
  connection: api.IConnection,
) {
  // Step 1: Create first member account (Member A)
  const memberAEmail = typia.random<string & tags.Format<"email">>();
  const memberAData = {
    email: memberAEmail,
    password: "password123",
    username: RandomGenerator.name(2),
    href: "https://example.com/register",
    referrer: "https://example.com/home",
  } satisfies IDiscussionBoardMember.ICreate;

  const memberA: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: memberAData,
    });
  typia.assert(memberA);

  // Step 2: Member A creates multiple articles (4 articles)
  const memberAArticles: IDiscussionBoardArticle[] =
    await ArrayUtil.asyncRepeat(4, async () => {
      const article = await api.functional.discussionBoard.articles.create(
        connection,
        {
          body: {
            title: RandomGenerator.paragraph({
              sentences: 3,
              wordMin: 3,
              wordMax: 7,
            }),
            body: RandomGenerator.content({
              paragraphs: 2,
              sentenceMin: 10,
              sentenceMax: 15,
            }),
          } satisfies IDiscussionBoardArticle.ICreate,
        },
      );
      typia.assert(article);
      return article;
    });

  // Step 3: Create second member account (Member B)
  const memberBEmail = typia.random<string & tags.Format<"email">>();
  const memberBData = {
    email: memberBEmail,
    password: "password456",
    username: RandomGenerator.name(2),
    href: "https://example.com/register",
    referrer: "https://example.com/home",
  } satisfies IDiscussionBoardMember.ICreate;

  const memberB: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: memberBData,
    });
  typia.assert(memberB);

  // Step 4: Member B creates multiple articles (3 articles)
  const memberBArticles: IDiscussionBoardArticle[] =
    await ArrayUtil.asyncRepeat(3, async () => {
      const article = await api.functional.discussionBoard.articles.create(
        connection,
        {
          body: {
            title: RandomGenerator.paragraph({
              sentences: 3,
              wordMin: 3,
              wordMax: 7,
            }),
            body: RandomGenerator.content({
              paragraphs: 2,
              sentenceMin: 10,
              sentenceMax: 15,
            }),
          } satisfies IDiscussionBoardArticle.ICreate,
        },
      );
      typia.assert(article);
      return article;
    });

  // Step 5: Filter articles by Member A's ID
  const filteredResults: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.articles.index(connection, {
      body: {
        discussion_board_member_id: memberA.id,
        page: 1,
        limit: 20,
      } satisfies IDiscussionBoardArticle.IRequest,
    });
  typia.assert(filteredResults);

  // Step 6: Validate filtered results contain ONLY Member A's articles
  TestValidator.equals(
    "filtered article count matches Member A's article count",
    filteredResults.data.length,
    memberAArticles.length,
  );

  TestValidator.equals(
    "total records in pagination matches Member A's article count",
    filteredResults.pagination.records,
    memberAArticles.length,
  );

  // Step 7: Verify each filtered article belongs to Member A
  await ArrayUtil.asyncForEach(filteredResults.data, async (articleSummary) => {
    TestValidator.equals(
      "article author ID matches Member A ID",
      articleSummary.author.id,
      memberA.id,
    );

    TestValidator.equals(
      "article author username matches Member A username",
      articleSummary.author.username,
      memberA.username,
    );

    TestValidator.equals(
      "article author email matches Member A email",
      articleSummary.author.email,
      memberA.email,
    );
  });

  // Step 8: Verify Member B's articles are NOT in the filtered results
  const memberAArticleIds = memberAArticles.map((a) => a.id);
  const filteredArticleIds = filteredResults.data.map((a) => a.id);

  TestValidator.predicate(
    "all filtered article IDs are from Member A",
    filteredArticleIds.every((id) => memberAArticleIds.includes(id)),
  );

  // Step 9: Verify none of Member B's articles appear in filtered results
  const memberBArticleIds = memberBArticles.map((a) => a.id);
  TestValidator.predicate(
    "no Member B articles appear in filtered results",
    filteredArticleIds.every((id) => !memberBArticleIds.includes(id)),
  );

  // Step 10: Verify pagination metadata correctness
  TestValidator.equals(
    "pagination current page is 1",
    filteredResults.pagination.current,
    1,
  );

  TestValidator.equals(
    "pagination limit matches request",
    filteredResults.pagination.limit,
    20,
  );

  TestValidator.predicate(
    "pagination pages is calculated correctly",
    filteredResults.pagination.pages >= 1,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticle";

/**
 * Test date range filtering capabilities for discussion board articles.
 *
 * This test validates the date range filtering functionality using
 * created_at_from and created_at_to parameters to discover articles within
 * specific time periods.
 *
 * Test process:
 *
 * 1. Create authenticated member account
 * 2. Create multiple articles at different timestamps with deliberate delays
 * 3. Test complete date range filtering (both from and to)
 * 4. Test single-sided range filtering (only from or only to)
 * 5. Test exact timestamp boundaries
 * 6. Test empty result sets when no articles match criteria
 * 7. Validate ISO 8601 date-time format handling and timestamp comparisons
 */
export async function test_api_article_date_range_filtering(
  connection: api.IConnection,
) {
  // Step 1: Create authenticated member account
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      password: "testPassword123!",
      username: RandomGenerator.name(),
      href: "https://test.com/register",
      referrer: "https://test.com/home",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Step 2: Create multiple articles at different timestamps with controlled delays
  const articles: IDiscussionBoardArticle[] = [];
  const articleCount = 5;

  for (let i = 0; i < articleCount; i++) {
    const article = await api.functional.discussionBoard.articles.create(
      connection,
      {
        body: {
          title: `Test Article ${i + 1} - ${RandomGenerator.name()}`,
          body: RandomGenerator.content({ paragraphs: 2 }),
        } satisfies IDiscussionBoardArticle.ICreate,
      },
    );
    typia.assert(article);
    articles.push(article);

    // Add delay between article creations to ensure different timestamps
    if (i < articleCount - 1) {
      await new Promise((resolve) => setTimeout(resolve, 100));
    }
  }

  // Step 3: Test complete date range filtering (both from and to)
  const firstArticle = articles[0];
  const lastArticle = articles[articleCount - 1];
  const middleIndex = Math.floor(articleCount / 2);
  const middleArticle = articles[middleIndex];

  // Test: Filter articles from first to middle
  const rangeResult1 = await api.functional.discussionBoard.articles.index(
    connection,
    {
      body: {
        created_at_from: firstArticle.created_at,
        created_at_to: middleArticle.created_at,
      } satisfies IDiscussionBoardArticle.IRequest,
    },
  );
  typia.assert(rangeResult1);

  TestValidator.predicate(
    "range filtering from first to middle should return expected count",
    rangeResult1.data.length >= 1 &&
      rangeResult1.data.length <= middleIndex + 1,
  );

  // Verify all returned articles are within the date range
  for (const article of rangeResult1.data) {
    const articleDate = new Date(article.created_at);
    const fromDate = new Date(firstArticle.created_at);
    const toDate = new Date(middleArticle.created_at);

    TestValidator.predicate(
      `article ${article.id} timestamp within range`,
      articleDate >= fromDate && articleDate <= toDate,
    );
  }

  // Step 4: Test single-sided range filtering (only from)
  const fromOnlyResult = await api.functional.discussionBoard.articles.index(
    connection,
    {
      body: {
        created_at_from: middleArticle.created_at,
      } satisfies IDiscussionBoardArticle.IRequest,
    },
  );
  typia.assert(fromOnlyResult);

  TestValidator.predicate(
    "from-only filtering should return articles",
    fromOnlyResult.data.length >= 1,
  );

  for (const article of fromOnlyResult.data) {
    const articleDate = new Date(article.created_at);
    const fromDate = new Date(middleArticle.created_at);

    TestValidator.predicate(
      `article ${article.id} created after from date`,
      articleDate >= fromDate,
    );
  }

  // Step 5: Test single-sided range filtering (only to)
  const toOnlyResult = await api.functional.discussionBoard.articles.index(
    connection,
    {
      body: {
        created_at_to: middleArticle.created_at,
      } satisfies IDiscussionBoardArticle.IRequest,
    },
  );
  typia.assert(toOnlyResult);

  TestValidator.predicate(
    "to-only filtering should return articles",
    toOnlyResult.data.length >= 1,
  );

  for (const article of toOnlyResult.data) {
    const articleDate = new Date(article.created_at);
    const toDate = new Date(middleArticle.created_at);

    TestValidator.predicate(
      `article ${article.id} created before to date`,
      articleDate <= toDate,
    );
  }

  // Step 6: Test exact timestamp boundaries
  const exactBoundaryResult =
    await api.functional.discussionBoard.articles.index(connection, {
      body: {
        created_at_from: firstArticle.created_at,
        created_at_to: firstArticle.created_at,
      } satisfies IDiscussionBoardArticle.IRequest,
    });
  typia.assert(exactBoundaryResult);

  TestValidator.predicate(
    "exact timestamp boundary should include the article",
    exactBoundaryResult.data.some((a) => a.id === firstArticle.id),
  );

  // Step 7: Test empty result sets when no articles match criteria
  const futureDate = new Date(Date.now() + 1000 * 60 * 60 * 24 * 365);
  const futureDateIso = futureDate.toISOString();

  const emptyResult = await api.functional.discussionBoard.articles.index(
