  } satisfies IDiscussionBoardMember.ICreate;

  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: memberData,
    });
  typia.assert(member);

  // Step 2: Create 5 initial articles
  const articles: IDiscussionBoardArticle[] = await ArrayUtil.asyncRepeat(
    5,
    async (index) => {
      const articleData = {
        title: `Test Article ${index + 1} - ${RandomGenerator.paragraph({ sentences: 3 })}`,
        body: RandomGenerator.content({
          paragraphs: 2,
          sentenceMin: 10,
          sentenceMax: 20,
        }),
      } satisfies IDiscussionBoardArticle.ICreate;

      const article: IDiscussionBoardArticle =
        await api.functional.discussionBoard.articles.create(connection, {
          body: articleData,
        });
      typia.assert(article);
      return article;
    },
  );

  // Step 3: Wait briefly to ensure timestamp differences, then update 3 articles
  // Update articles in a specific order: articles[1], articles[3], articles[0]
  await new Promise((resolve) => setTimeout(resolve, 100));

  const updateData1 = {
    body: RandomGenerator.content({
      paragraphs: 1,
      sentenceMin: 5,
      sentenceMax: 10,
    }),
  } satisfies IDiscussionBoardArticle.IUpdate;

  const updatedArticle1: IDiscussionBoardArticle =
    await api.functional.discussionBoard.articles.update(connection, {
      articleId: articles[1].id,
      body: updateData1,
    });
  typia.assert(updatedArticle1);

  await new Promise((resolve) => setTimeout(resolve, 100));

  const updateData2 = {
    title: `Updated Article - ${RandomGenerator.paragraph({ sentences: 2 })}`,
  } satisfies IDiscussionBoardArticle.IUpdate;

  const updatedArticle2: IDiscussionBoardArticle =
    await api.functional.discussionBoard.articles.update(connection, {
      articleId: articles[3].id,
      body: updateData2,
    });
  typia.assert(updatedArticle2);

  await new Promise((resolve) => setTimeout(resolve, 100));

  const updateData3 = {
    title: `Most Recently Updated - ${RandomGenerator.paragraph({ sentences: 2 })}`,
    body: RandomGenerator.content({
      paragraphs: 1,
      sentenceMin: 8,
      sentenceMax: 15,
    }),
  } satisfies IDiscussionBoardArticle.IUpdate;

  const updatedArticle3: IDiscussionBoardArticle =
    await api.functional.discussionBoard.articles.update(connection, {
      articleId: articles[0].id,
      body: updateData3,
    });
  typia.assert(updatedArticle3);

  // Step 4: Query search API with sort_by='updated_at' and sort_order='desc'
  const searchRequest = {
    sort_by: "updated_at",
    sort_order: "desc",
    page: 1,
    limit: 10,
  } satisfies IDiscussionBoardArticle.IRequest;

  const searchResult: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.articles.index(connection, {
      body: searchRequest,
    });
  typia.assert(searchResult);

  // Step 5: Validate that articles are returned in correct order
  // Expected order: articles[0], articles[3], articles[1], articles[2], articles[4]
  // (most recently updated first)

  TestValidator.predicate(
    "search result should contain articles",
    searchResult.data.length >= 3,
  );

  // Find our test articles in the results
  const ourArticleIds = articles.map((a) => a.id);
  const resultArticles = searchResult.data.filter((article) =>
    ourArticleIds.includes(article.id),
  );

  TestValidator.predicate(
    "should find all created articles in results",
    resultArticles.length === 5,
  );

  // Verify the order: most recently updated should be first
  const article0Index = resultArticles.findIndex(
    (a) => a.id === articles[0].id,
  );
  const article3Index = resultArticles.findIndex(
    (a) => a.id === articles[3].id,
  );
  const article1Index = resultArticles.findIndex(
    (a) => a.id === articles[1].id,
  );

  TestValidator.predicate(
    "most recently updated article (articles[0]) should appear before articles[3]",
    article0Index < article3Index,
  );

  TestValidator.predicate(
    "articles[3] should appear before articles[1]",
    article3Index < article1Index,
  );

  // Verify updated_at timestamps are in descending order for our articles
  for (let i = 0; i < resultArticles.length - 1; i++) {
    const currentUpdatedAt = new Date(resultArticles[i].updated_at).getTime();
    const nextUpdatedAt = new Date(resultArticles[i + 1].updated_at).getTime();

    TestValidator.predicate(
      `article at index ${i} should have updated_at >= article at index ${i + 1}`,
      currentUpdatedAt >= nextUpdatedAt,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticle";

/**
 * Test pagination controls by creating a large set of articles and navigating
 * through multiple pages.
 *
 * This test validates comprehensive pagination functionality including:
 *
 * 1. Creating a member account for authentication
 * 2. Generating a large dataset of articles (40 articles) to enable multi-page
 *    testing
 * 3. Testing different page sizes (limit values: 1, 5, 10, 20, 50, 100)
 * 4. Testing page navigation across multiple pages (page 1, 2, 3, etc.)
 * 5. Testing edge cases: first page, last page, empty pages beyond available data
 * 6. Validating pagination metadata accuracy: total records, total pages, current
 *    page, limit
 *
 * The test ensures robust pagination implementation by verifying correct data
 * retrieval, accurate metadata calculation, and proper handling of boundary
 * conditions.
 */
export async function test_api_article_pagination_navigation(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate member account
  const memberData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "testPassword123",
    username: RandomGenerator.name(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMember.ICreate;

  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: memberData,
    });
  typia.assert(member);

  // Step 2: Generate large article dataset (40 articles)
  const articleCount = 40;
  const createdArticles: IDiscussionBoardArticle[] =
    await ArrayUtil.asyncRepeat(articleCount, async (index) => {
      const articleData = {
        title: `Test Article ${index + 1} - ${RandomGenerator.name(3)}`,
        body: RandomGenerator.content({
          paragraphs: 3,
          sentenceMin: 10,
          sentenceMax: 20,
        }),
      } satisfies IDiscussionBoardArticle.ICreate;

      const article: IDiscussionBoardArticle =
        await api.functional.discussionBoard.articles.create(connection, {
          body: articleData,
        });
      typia.assert(article);
      return article;
    });

  // Step 3: Test various page sizes (limit values)
  const limitTests = [1, 5, 10, 20, 50, 100] as const;
  for (const limit of limitTests) {
    const result: IPageIDiscussionBoardArticle.ISummary =
      await api.functional.discussionBoard.articles.index(connection, {
        body: {
          page: 1,
          limit: limit,
        } satisfies IDiscussionBoardArticle.IRequest,
      });
    typia.assert(result);

    // Validate pagination metadata
    TestValidator.equals(
      "total records matches article count",
      result.pagination.records,
      articleCount,
    );

    const expectedPages = Math.ceil(articleCount / limit);
    TestValidator.equals(
      "total pages calculation correct",
      result.pagination.pages,
      expectedPages,
    );
    TestValidator.equals("current page is 1", result.pagination.current, 1);
    TestValidator.equals(
      "limit matches request",
      result.pagination.limit,
      limit,
    );

    // Validate data array length
    const expectedDataLength = Math.min(limit, articleCount);
    TestValidator.equals(
      "data length matches limit or remaining articles",
      result.data.length,
      expectedDataLength,
    );
  }

  // Step 4: Test page navigation with fixed limit
  const navigationLimit = 10;
  const totalPages = Math.ceil(articleCount / navigationLimit);

  for (let pageNum = 1; pageNum <= totalPages; pageNum++) {
    const pageResult: IPageIDiscussionBoardArticle.ISummary =
      await api.functional.discussionBoard.articles.index(connection, {
        body: {
          page: pageNum,
          limit: navigationLimit,
        } satisfies IDiscussionBoardArticle.IRequest,
      });
    typia.assert(pageResult);

    TestValidator.equals(
      "current page matches request",
      pageResult.pagination.current,
      pageNum,
    );
    TestValidator.equals(
      "records count consistent",
      pageResult.pagination.records,
      articleCount,
    );
    TestValidator.equals(
      "total pages consistent",
      pageResult.pagination.pages,
      totalPages,
    );
    TestValidator.equals(
      "limit consistent",
      pageResult.pagination.limit,
      navigationLimit,
    );

    // Validate data length for each page
    const isLastPage = pageNum === totalPages;
    const expectedLength = isLastPage
      ? articleCount - (pageNum - 1) * navigationLimit
      : navigationLimit;
    TestValidator.equals(
      "page data length correct",
      pageResult.data.length,
      expectedLength,
    );
  }

  // Step 5: Test edge case - first page explicitly
  const firstPage: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.articles.index(connection, {
