import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticle";

/**
 * Test that article search automatically excludes soft-deleted articles from
 * results.
 *
 * This test validates that the search operation respects the deleted_at field
 * and maintains content integrity by hiding moderated or removed articles from
 * public discovery. It ensures pagination counts and metadata exclude deleted
 * articles from totals.
 *
 * Test Flow:
 *
 * 1. Create a member account for authentication
 * 2. Create multiple articles with distinct, searchable titles
 * 3. Soft-delete some of the created articles
 * 4. Perform search operations to retrieve articles
 * 5. Validate that deleted articles do not appear in search results
 * 6. Verify pagination metadata excludes deleted articles from counts
 */
export async function test_api_article_search_excludes_deleted_content(
  connection: api.IConnection,
) {
  // Step 1: Create member account for authentication
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "testPassword123";
  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      username: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Step 2: Create multiple articles with distinct titles
  const articleTitles = [
    "Economy Discussion Article One",
    "Political Analysis Article Two",
    "Market Trends Article Three",
    "Government Policy Article Four",
    "Trade Relations Article Five",
  ];

  const createdArticles: IDiscussionBoardArticle[] = [];

  for (const title of articleTitles) {
    const article = await api.functional.discussionBoard.articles.create(
      connection,
      {
        body: {
          title: title,
          body: RandomGenerator.content({ paragraphs: 3 }),
        } satisfies IDiscussionBoardArticle.ICreate,
      },
    );
    typia.assert(article);
    createdArticles.push(article);
  }

  TestValidator.equals(
    "created all articles",
    createdArticles.length,
    articleTitles.length,
  );

  // Step 3: Soft-delete some articles (delete first 2 articles)
  const articlesToDelete = createdArticles.slice(0, 2);
  const activeArticles = createdArticles.slice(2);

  for (const article of articlesToDelete) {
    const deletedArticle =
      await api.functional.discussionBoard.member.articles.erase(connection, {
        articleId: article.id,
      });
    typia.assert(deletedArticle);
    TestValidator.predicate(
      "article has deleted_at timestamp",
      deletedArticle.deleted_at !== null,
    );
  }

  // Step 4: Perform search to retrieve all articles
  const searchResult = await api.functional.discussionBoard.articles.index(
    connection,
    {
      body: {} satisfies IDiscussionBoardArticle.IRequest,
    },
  );
  typia.assert(searchResult);

  // Step 5: Validate deleted articles are excluded from search results
  const returnedArticleIds = searchResult.data.map((article) => article.id);
  const deletedArticleIds = articlesToDelete.map((article) => article.id);
  const activeArticleIds = activeArticles.map((article) => article.id);

  for (const deletedId of deletedArticleIds) {
    TestValidator.predicate(
      "deleted article not in search results",
      returnedArticleIds.includes(deletedId) === false,
    );
  }

  // Verify active articles are still present
  for (const activeId of activeArticleIds) {
    TestValidator.predicate(
      "active article is in search results",
      returnedArticleIds.includes(activeId),
    );
  }

  // Step 6: Verify pagination metadata excludes deleted articles
  TestValidator.predicate(
    "pagination records count excludes deleted articles",
    searchResult.pagination.records >= activeArticles.length,
  );

  // Additional test: Search with keyword that matches deleted article
  const deletedArticleTitle = articlesToDelete[0].title;
  const searchKeyword = deletedArticleTitle.split(" ")[0];

  const keywordSearchResult =
    await api.functional.discussionBoard.articles.index(connection, {
      body: {
        search: searchKeyword,
      } satisfies IDiscussionBoardArticle.IRequest,
    });
  typia.assert(keywordSearchResult);

  const keywordResultIds = keywordSearchResult.data.map(
    (article) => article.id,
  );

  for (const deletedId of deletedArticleIds) {
    TestValidator.predicate(
      "deleted article not in keyword search results",
      keywordResultIds.includes(deletedId) === false,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticle";

/**
 * Test edge cases where search criteria return no matching articles.
 *
 * This test validates that the article search API properly handles empty result
 * sets when search criteria match no articles. It ensures that the API returns
 * proper pagination metadata with zero records and pages, empty data arrays,
 * and appropriate response structure without errors across multiple no-results
 * scenarios.
 *
 * Test scenarios:
 *
 * 1. Search with non-existent keywords
 * 2. Filter by non-existent author IDs
 * 3. Use date ranges with no articles
 * 4. Request pages beyond available data
 */
export async function test_api_article_empty_search_results(
  connection: api.IConnection,
) {
  // Scenario 1: Search with keyword that doesn't exist in any article
  const nonExistentKeyword = typia.random<string & tags.Format<"uuid">>();
  const emptySearchResult: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.articles.index(connection, {
      body: {
        search: nonExistentKeyword,
      } satisfies IDiscussionBoardArticle.IRequest,
    });
  typia.assert(emptySearchResult);

  TestValidator.equals(
    "empty search returns zero records",
    emptySearchResult.pagination.records,
    0,
  );
  TestValidator.equals(
    "empty search returns zero pages",
    emptySearchResult.pagination.pages,
    0,
  );
  TestValidator.equals(
    "empty search returns empty data array",
    emptySearchResult.data.length,
    0,
  );
  TestValidator.predicate(
    "data array is empty",
    emptySearchResult.data.length === 0,
  );

  // Scenario 2: Filter by non-existent author ID
  const nonExistentAuthorId = typia.random<string & tags.Format<"uuid">>();
  const emptyAuthorResult: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.articles.index(connection, {
      body: {
        discussion_board_member_id: nonExistentAuthorId,
      } satisfies IDiscussionBoardArticle.IRequest,
    });
  typia.assert(emptyAuthorResult);

  TestValidator.equals(
    "non-existent author returns zero records",
    emptyAuthorResult.pagination.records,
    0,
  );
  TestValidator.equals(
    "non-existent author returns zero pages",
    emptyAuthorResult.pagination.pages,
    0,
  );
  TestValidator.equals(
    "non-existent author returns empty data array",
    emptyAuthorResult.data.length,
    0,
  );

  // Scenario 3: Date range with no articles
  const futureDate = new Date(Date.now() + 365 * 24 * 60 * 60 * 1000);
  const farFutureDate = new Date(Date.now() + 730 * 24 * 60 * 60 * 1000);

  const emptyDateRangeResult: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.articles.index(connection, {
      body: {
        created_at_from: futureDate.toISOString(),
        created_at_to: farFutureDate.toISOString(),
      } satisfies IDiscussionBoardArticle.IRequest,
    });
  typia.assert(emptyDateRangeResult);

  TestValidator.equals(
    "future date range returns zero records",
    emptyDateRangeResult.pagination.records,
    0,
  );
  TestValidator.equals(
    "future date range returns zero pages",
    emptyDateRangeResult.pagination.pages,
    0,
  );
  TestValidator.equals(
    "future date range returns empty data array",
    emptyDateRangeResult.data.length,
    0,
  );

  // Scenario 4: Request page beyond available data
  const beyondPageResult: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.articles.index(connection, {
      body: {
        search: nonExistentKeyword,
        page: 999,
        limit: 10,
      } satisfies IDiscussionBoardArticle.IRequest,
    });
  typia.assert(beyondPageResult);

  TestValidator.equals(
    "page beyond data returns zero records",
    beyondPageResult.pagination.records,
    0,
  );
  TestValidator.equals(
    "page beyond data returns zero pages",
    beyondPageResult.pagination.pages,
    0,
  );
  TestValidator.equals(
    "page beyond data returns empty data array",
    beyondPageResult.data.length,
    0,
  );

  // Scenario 5: Combined filters with no matches
  const combinedEmptyResult: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.articles.index(connection, {
      body: {
        search: nonExistentKeyword,
        discussion_board_member_id: nonExistentAuthorId,
        created_at_from: futureDate.toISOString(),
        sort_by: "created_at",
        sort_order: "desc",
        page: 1,
        limit: 20,
      } satisfies IDiscussionBoardArticle.IRequest,
    });
  typia.assert(combinedEmptyResult);

  TestValidator.equals(
    "combined filters return zero records",
    combinedEmptyResult.pagination.records,
    0,
  );
  TestValidator.equals(
    "combined filters return zero pages",
    combinedEmptyResult.pagination.pages,
    0,
  );
  TestValidator.equals(
    "combined filters return empty data array",
    combinedEmptyResult.data.length,
    0,
  );

  // Verify pagination metadata consistency across all empty results
  const allEmptyResults = [
    emptySearchResult,
    emptyAuthorResult,
    emptyDateRangeResult,
    beyondPageResult,
    combinedEmptyResult,
  ];

  for (const result of allEmptyResults) {
    TestValidator.predicate(
      "pagination current is non-negative",
      result.pagination.current >= 0,
    );
    TestValidator.predicate(
      "pagination limit is non-negative",
      result.pagination.limit >= 0,
    );
    TestValidator.predicate(
      "empty results have consistent structure",
      result.pagination.records === 0 &&
        result.pagination.pages === 0 &&
        result.data.length === 0,
    );
  }
}

