import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Test retrieving image attachments where width and height dimensions are null.
 *
 * This scenario validates that the system correctly handles images where
 * dimension information could not be determined during upload. Creates an
 * article as a member, uploads an image attachment with null width and height
 * values (simulating cases where dimensions are unavailable), then retrieves
 * the image details. Verifies that the response correctly includes null values
 * for width and height fields while all other required metadata (id,
 * original_filename, file_size, content_type, storage_url, created_at) are
 * properly populated.
 */
export async function test_api_article_image_nullable_dimensions(
  connection: api.IConnection,
) {
  // Step 1: Create a member account for authentication
  const memberData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    username: RandomGenerator.name(2),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMember.ICreate;

  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: memberData,
    });
  typia.assert(member);

  // Step 2: Create an article to hold the image attachment
  const articleData = {
    title: RandomGenerator.paragraph({ sentences: 3, wordMin: 5, wordMax: 10 }),
    body: RandomGenerator.content({
      paragraphs: 2,
      sentenceMin: 10,
      sentenceMax: 20,
    }),
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: articleData,
    });
  typia.assert(article);

  // Step 3: Upload an image with null width and height (simulating missing dimension info)
  const imageData = {
    original_filename: `${RandomGenerator.name(1)}.png`,
    file_size: typia.random<
      number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<10485760>
    >(),
    content_type: "image/png",
    storage_url: typia.random<string & tags.Format<"uri">>(),
    width: null,
    height: null,
  } satisfies IDiscussionBoardArticleImage.ICreate;

  const uploadedImage: IDiscussionBoardArticleImage =
    await api.functional.discussionBoard.member.articles.images.create(
      connection,
      {
        articleId: article.id,
        body: imageData,
      },
    );
  typia.assert(uploadedImage);

  // Step 4: Retrieve the image details to verify null dimensions are handled correctly
  const retrievedImage: IDiscussionBoardArticleImage =
    await api.functional.discussionBoard.articles.images.at(connection, {
      articleId: article.id,
      imageId: uploadedImage.id,
    });
  typia.assert(retrievedImage);

  // Step 5: Validate that all required metadata is properly populated
  TestValidator.equals("image ID matches", retrievedImage.id, uploadedImage.id);
  TestValidator.equals(
    "article ID matches",
    retrievedImage.discussion_board_article_id,
    article.id,
  );
  TestValidator.equals(
    "original filename matches",
    retrievedImage.original_filename,
    imageData.original_filename,
  );
  TestValidator.equals(
    "file size matches",
    retrievedImage.file_size,
    imageData.file_size,
  );
  TestValidator.equals(
    "content type matches",
    retrievedImage.content_type,
    imageData.content_type,
  );
  TestValidator.equals(
    "storage URL matches",
    retrievedImage.storage_url,
    imageData.storage_url,
  );

  // Step 6: Verify that width and height are null (critical validation)
  TestValidator.equals("width is null", retrievedImage.width, null);
  TestValidator.equals("height is null", retrievedImage.height, null);

  // Step 7: Verify timestamp fields are populated
  TestValidator.predicate(
    "created_at is populated",
    retrievedImage.created_at !== null &&
      retrievedImage.created_at !== undefined,
  );
  TestValidator.predicate(
    "deleted_at is null for active image",
    retrievedImage.deleted_at === null ||
      retrievedImage.deleted_at === undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleImage";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

export async function test_api_article_image_various_content_types(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate a new member account
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "testPassword123";
  const memberUsername = RandomGenerator.name();

  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      username: memberUsername,
      href: "https://test.example.com/register",
      referrer: "https://test.example.com/home",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Step 2: Create a discussion board article
  const article = await api.functional.discussionBoard.member.articles.create(
    connection,
    {
      body: {
        title: "Testing Multiple Image Formats in Articles",
        body: "This article tests the support for various image content types including JPEG, PNG, GIF, and WebP formats.",
      } satisfies IDiscussionBoardArticle.ICreate,
    },
  );
  typia.assert(article);

  // Step 3: Define image content types to test
  const contentTypes = [
    "image/jpeg",
    "image/png",
    "image/gif",
    "image/webp",
  ] as const;

  const extensions = {
    "image/jpeg": ".jpg",
    "image/png": ".png",
    "image/gif": ".gif",
    "image/webp": ".webp",
  };

  // Step 4: Upload images with different content types
  const uploadedImages: IDiscussionBoardArticleImage[] = [];

  for (const contentType of contentTypes) {
    const extension = extensions[contentType];
    const imageData = {
      original_filename: `test_image_${RandomGenerator.alphabets(6)}${extension}`,
      file_size: typia.random<
        number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<5000000>
      >(),
      content_type: contentType,
      storage_url: typia.random<string & tags.Format<"uri">>(),
      width: typia.random<
        number & tags.Type<"int32"> & tags.Minimum<100> & tags.Maximum<4000>
      >(),
      height: typia.random<
        number & tags.Type<"int32"> & tags.Minimum<100> & tags.Maximum<4000>
      >(),
    } satisfies IDiscussionBoardArticleImage.ICreate;

    const uploadedImage =
      await api.functional.discussionBoard.member.articles.images.create(
        connection,
        {
          articleId: article.id,
          body: imageData,
        },
      );
    typia.assert(uploadedImage);
    uploadedImages.push(uploadedImage);
  }

  // Step 5: Retrieve each image and verify content type preservation
  for (let i = 0; i < uploadedImages.length; i++) {
    const uploadedImage = uploadedImages[i];
    const expectedContentType = contentTypes[i];

    const retrievedImage =
      await api.functional.discussionBoard.articles.images.at(connection, {
        articleId: article.id,
        imageId: uploadedImage.id,
      });
    typia.assert(retrievedImage);

    // Validate content type matches
    TestValidator.equals(
      `image ${i + 1} content type should be ${expectedContentType}`,
      retrievedImage.content_type,
      expectedContentType,
    );

    // Validate other metadata is preserved
    TestValidator.equals(
      `image ${i + 1} ID matches`,
      retrievedImage.id,
      uploadedImage.id,
    );
    TestValidator.equals(
      `image ${i + 1} filename matches`,
      retrievedImage.original_filename,
      uploadedImage.original_filename,
    );
    TestValidator.equals(
      `image ${i + 1} file size matches`,
      retrievedImage.file_size,
      uploadedImage.file_size,
    );
    TestValidator.equals(
      `image ${i + 1} storage URL matches`,
      retrievedImage.storage_url,
      uploadedImage.storage_url,
    );
    TestValidator.equals(
      `image ${i + 1} width matches`,
      retrievedImage.width,
      uploadedImage.width,
    );
    TestValidator.equals(
      `image ${i + 1} height matches`,
      retrievedImage.height,
      uploadedImage.height,
    );
  }

  // Validate all four content types were tested
  TestValidator.equals(
    "all four image formats were tested",
    uploadedImages.length,
    4,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleFile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticleFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticleFile";

/**
 * Test retrieving a paginated list of file attachments for a specific article
 * with basic pagination parameters.
 *
 * This test validates that file attachments can be successfully listed with
 * pagination controls including page number and limit. The test creates an
 * article as a member, uploads multiple file attachments (at least 5 files)
 * with various names and types, then retrieves the file list with pagination
 * parameters (page 1, limit 3).
 *
 * The test verifies:
 *
 * 1. Pagination metadata includes correct values (current page, limit, total
 *    records, total pages)
 * 2. Data array contains file summaries with all required fields: id (UUID), name
 *    (original filename), extension (file type suffix), url (storage URL), size
 *    (bytes), and content_type (MIME type)
 * 3. Pagination correctly limits results to the specified page size
 * 4. Total counts are accurate
 */
export async function test_api_article_files_paginated_retrieval(
  connection: api.IConnection,
) {
  // Step 1: Create member account for authentication
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "testPassword123";
  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      username: RandomGenerator.name(),
      ip: "127.0.0.1",
      href: "https://example.com/register",
      referrer: "https://example.com/home",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Step 2: Create parent article to attach files to
  const article = await api.functional.discussionBoard.articles.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 3 }),
        body: RandomGenerator.content({ paragraphs: 3 }),
      } satisfies IDiscussionBoardArticle.ICreate,
    },
  );
  typia.assert(article);

  // Step 3: Upload multiple file attachments (at least 5 files) with various names and types
  const fileCount = 6;
  const uploadedFiles: IDiscussionBoardArticleFile[] = [];

  const fileTypes = [
    { ext: "pdf", mime: "application/pdf" },
    {
      ext: "docx",
      mime: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    },
    {
      ext: "xlsx",
      mime: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    },
    { ext: "txt", mime: "text/plain" },
    { ext: "csv", mime: "text/csv" },
    { ext: "zip", mime: "application/zip" },
  ];

  for (let i = 0; i < fileCount; i++) {
    const fileType = fileTypes[i];
    const fileName = `${RandomGenerator.name()}_document_${i + 1}.${fileType.ext}`;
    const fileSize = typia.random<
      number & tags.Type<"int32"> & tags.Minimum<1000> & tags.Maximum<5000000>
    >();

    const uploadedFile =
      await api.functional.discussionBoard.member.articles.files.create(
        connection,
        {
          articleId: article.id,
          body: {
            original_filename: fileName,
            file_size: fileSize,
            content_type: fileType.mime,
            storage_url: `https://cdn.example.com/files/${typia.random<string & tags.Format<"uuid">>()}/${fileName}`,
          } satisfies IDiscussionBoardArticleFile.ICreate,
        },
      );
    typia.assert(uploadedFile);
    uploadedFiles.push(uploadedFile);
  }

  // Step 4: Retrieve file list with pagination parameters (page 1, limit 3)
  const pageNumber = 1;
  const pageLimit = 3;

  const paginatedResult =
    await api.functional.discussionBoard.articles.files.index(connection, {
      articleId: article.id,
      body: {
        page: pageNumber,
        limit: pageLimit,
      } satisfies IDiscussionBoardArticleFile.IRequest,
    });
  typia.assert(paginatedResult);

  // Step 5: Validate pagination metadata
  TestValidator.equals(
    "pagination current page should be 1",
    paginatedResult.pagination.current,
    pageNumber,
  );

  TestValidator.equals(
    "pagination limit should be 3",
    paginatedResult.pagination.limit,
    pageLimit,
  );

  TestValidator.equals(
    "pagination total records should match uploaded file count",
    paginatedResult.pagination.records,
    fileCount,
  );

  const expectedPages = Math.ceil(fileCount / pageLimit);
  TestValidator.equals(
    "pagination total pages should be calculated correctly",
    paginatedResult.pagination.pages,
    expectedPages,
  );

  // Step 6: Validate data array length matches limit
  TestValidator.equals(
    "data array should contain exactly 3 items (page limit)",
    paginatedResult.data.length,
    pageLimit,
  );

  // Step 7: Validate each file summary contains all required fields with correct types
  for (const fileSummary of paginatedResult.data) {
    typia.assert(fileSummary);

    TestValidator.predicate(
      "file id should be valid UUID format",
      typia.is<string & tags.Format<"uuid">>(fileSummary.id),
    );

    TestValidator.predicate(
      "file name should be non-empty string",
      typeof fileSummary.name === "string" && fileSummary.name.length > 0,
    );

    TestValidator.predicate(
      "file extension should be non-empty string",
      typeof fileSummary.extension === "string" &&
        fileSummary.extension.length > 0,
    );

    TestValidator.predicate(
      "file url should be valid URI format",
      typia.is<string & tags.Format<"uri">>(fileSummary.url),
    );

    TestValidator.predicate(
      "file size should be positive integer",
      typeof fileSummary.size === "number" && fileSummary.size > 0,
    );

    TestValidator.predicate(
      "content_type should be non-empty string",
      typeof fileSummary.content_type === "string" &&
        fileSummary.content_type.length > 0,
    );
  }

  // Step 8: Verify the returned files are from the uploaded files
  for (const fileSummary of paginatedResult.data) {
    const matchingFile = uploadedFiles.find((f) => f.id === fileSummary.id);
    TestValidator.predicate(
      "returned file should match one of the uploaded files",
      matchingFile !== undefined,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleFile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticleFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticleFile";

/**
 * Test filtering file attachments by filename using the search parameter.
 *
 * This test validates that file search functionality works correctly with
 * case-insensitive partial matching against original filenames. Creates an
 * article as a member, uploads several files with distinct names like
 * 'economic_report.pdf', 'political_analysis.docx', 'budget_data.xlsx', and
 * 'meeting_notes.txt'. Uses the search parameter to find files containing
 * 'report' and verifies only matching files are returned. Tests multiple search
 * queries with different patterns to ensure partial matching works correctly
 * and that search is case-insensitive. Verifies pagination metadata reflects
 * the filtered result count rather than total files.
 */
export async function test_api_article_files_search_by_filename(
  connection: api.IConnection,
) {
  // Step 1: Create a member account
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      password: "TestPassword123!",
      username: RandomGenerator.name(),
      href: "https://test.example.com/register",
      referrer: "https://test.example.com/home",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Step 2: Create an article to attach files to
  const article = await api.functional.discussionBoard.articles.create(
    connection,
    {
      body: {
        title: "Economic and Political Analysis Article",
        body: "This article contains various supporting documents for economic and political discussions.",
      } satisfies IDiscussionBoardArticle.ICreate,
    },
  );
  typia.assert(article);

  // Step 3: Upload multiple files with distinct, searchable names
  const fileData = [
    {
      original_filename: "economic_report.pdf",
      content_type: "application/pdf",
      file_size: 524288,
      storage_url: "https://storage.example.com/files/economic_report.pdf",
    },
    {
      original_filename: "political_analysis.docx",
      content_type:
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      file_size: 102400,
      storage_url: "https://storage.example.com/files/political_analysis.docx",
    },
    {
      original_filename: "budget_data.xlsx",
      content_type:
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      file_size: 204800,
      storage_url: "https://storage.example.com/files/budget_data.xlsx",
    },
    {
      original_filename: "meeting_notes.txt",
      content_type: "text/plain",
      file_size: 4096,
      storage_url: "https://storage.example.com/files/meeting_notes.txt",
    },
  ];

  const uploadedFiles = await ArrayUtil.asyncMap(fileData, async (file) => {
    const uploaded =
      await api.functional.discussionBoard.member.articles.files.create(
        connection,
        {
          articleId: article.id,
          body: {
            original_filename: file.original_filename,
            file_size: file.file_size,
            content_type: file.content_type,
            storage_url: file.storage_url,
          } satisfies IDiscussionBoardArticleFile.ICreate,
        },
      );
    typia.assert(uploaded);
    return uploaded;
  });

  // Step 4: Search for files containing "report"
  const reportSearchResult =
    await api.functional.discussionBoard.articles.files.index(connection, {
      articleId: article.id,
      body: {
        search: "report",
      } satisfies IDiscussionBoardArticleFile.IRequest,
    });
  typia.assert(reportSearchResult);

  // Step 5: Validate that only matching files are returned
  TestValidator.equals(
    "search 'report' should return 1 file",
    reportSearchResult.data.length,
    1,
  );
  TestValidator.equals(
    "found file should be economic_report.pdf",
    reportSearchResult.data[0].name,
    "economic_report.pdf",
  );
  TestValidator.equals(
    "pagination should reflect filtered count",
    reportSearchResult.pagination.records,
    1,
  );

  // Step 6: Test case-insensitive matching with "REPORT"
  const upperCaseSearchResult =
    await api.functional.discussionBoard.articles.files.index(connection, {
      articleId: article.id,
      body: {
        search: "REPORT",
      } satisfies IDiscussionBoardArticleFile.IRequest,
    });
  typia.assert(upperCaseSearchResult);

  TestValidator.equals(
    "case-insensitive search 'REPORT' should return 1 file",
    upperCaseSearchResult.data.length,
    1,
  );
  TestValidator.equals(
    "uppercase search should find economic_report.pdf",
    upperCaseSearchResult.data[0].name,
    "economic_report.pdf",
  );

  // Step 7: Test search with "analysis" pattern
  const analysisSearchResult =
    await api.functional.discussionBoard.articles.files.index(connection, {
      articleId: article.id,
      body: {
        search: "analysis",
      } satisfies IDiscussionBoardArticleFile.IRequest,
    });
  typia.assert(analysisSearchResult);

  TestValidator.equals(
    "search 'analysis' should return 1 file",
    analysisSearchResult.data.length,
    1,
  );
  TestValidator.equals(
    "found file should be political_analysis.docx",
    analysisSearchResult.data[0].name,
    "political_analysis.docx",
  );

  // Step 8: Test search with "data" pattern
  const dataSearchResult =
    await api.functional.discussionBoard.articles.files.index(connection, {
      articleId: article.id,
      body: {
        search: "data",
      } satisfies IDiscussionBoardArticleFile.IRequest,
    });
  typia.assert(dataSearchResult);

  TestValidator.equals(
    "search 'data' should return 1 file",
    dataSearchResult.data.length,
    1,
  );
  TestValidator.equals(
    "found file should be budget_data.xlsx",
    dataSearchResult.data[0].name,
    "budget_data.xlsx",
  );

  // Step 9: Test search with partial match "eco"
  const partialSearchResult =
    await api.functional.discussionBoard.articles.files.index(connection, {
      articleId: article.id,
      body: {
        search: "eco",
      } satisfies IDiscussionBoardArticleFile.IRequest,
    });
  typia.assert(partialSearchResult);

  TestValidator.equals(
    "partial search 'eco' should return 1 file",
    partialSearchResult.data.length,
    1,
  );
  TestValidator.equals(
    "partial match should find economic_report.pdf",
    partialSearchResult.data[0].name,
    "economic_report.pdf",
  );

  // Step 10: Test search with no matches
  const noMatchSearchResult =
    await api.functional.discussionBoard.articles.files.index(connection, {
      articleId: article.id,
      body: {
        search: "nonexistent",
      } satisfies IDiscussionBoardArticleFile.IRequest,
    });
  typia.assert(noMatchSearchResult);

  TestValidator.equals(
    "search with no matches should return empty array",
    noMatchSearchResult.data.length,
    0,
  );
  TestValidator.equals(
    "pagination records should be 0 for no matches",
    noMatchSearchResult.pagination.records,
    0,
  );

  // Step 11: Test search without search parameter returns all files
  const allFilesResult =
    await api.functional.discussionBoard.articles.files.index(connection, {
      articleId: article.id,
      body: {} satisfies IDiscussionBoardArticleFile.IRequest,
    });
  typia.assert(allFilesResult);

  TestValidator.equals(
    "request without search should return all 4 files",
    allFilesResult.data.length,
    4,
  );
  TestValidator.equals(
    "pagination should show total count of 4",
    allFilesResult.pagination.records,
    4,
  );
}

