import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleFile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticleFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticleFile";

/**
 * Test filtering file attachments by size range using min_size and max_size
 * parameters.
 *
 * This test validates that file size filtering helps users find files within
 * specific byte ranges. The test creates an article with files of varying sizes
 * (small, medium, large, very large) and tests filtering with min_size to
 * exclude small files, max_size to exclude large files, and combined range
 * queries. Validates that size field in response summaries falls within
 * specified ranges.
 *
 * Test Flow:
 *
 * 1. Register a new member account for authentication
 * 2. Create an article to attach files to
 * 3. Upload 4 files with different sizes:
 *
 *    - Small: 5000 bytes (< 10KB)
 *    - Medium: 50000 bytes (10KB-100KB)
 *    - Large: 500000 bytes (100KB-1MB)
 *    - Very Large: 2000000 bytes (> 1MB)
 * 4. Test min_size filtering (>= 10240 bytes) - should return medium, large, very
 *    large
 * 5. Test max_size filtering (<= 102400 bytes) - should return small, medium
 * 6. Test range query (min_size=10240, max_size=102400) - should return only
 *    medium
 * 7. Validate all returned file sizes are within the specified range
 */
export async function test_api_article_files_filter_by_size_range(
  connection: api.IConnection,
) {
  // Step 1: Register a new member account
  const memberData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "testPassword123!",
    username: RandomGenerator.name(),
    href: "https://example.com/register",
    referrer: "https://example.com/home",
  } satisfies IDiscussionBoardMember.ICreate;

  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: memberData,
    });
  typia.assert(member);

  // Step 2: Create an article to attach files to
  const articleData = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.articles.create(connection, {
      body: articleData,
    });
  typia.assert(article);

  // Step 3: Upload files with varying sizes
  const fileSizes = [
    { name: "small", size: 5000, description: "under 10KB" },
    { name: "medium", size: 50000, description: "10KB-100KB" },
    { name: "large", size: 500000, description: "100KB-1MB" },
    { name: "veryLarge", size: 2000000, description: "over 1MB" },
  ];

  const uploadedFiles: IDiscussionBoardArticleFile[] = [];

  for (const fileSpec of fileSizes) {
    const fileData = {
      original_filename: `${fileSpec.name}_file_${fileSpec.size}.pdf`,
      file_size: fileSpec.size,
      content_type: "application/pdf",
      storage_url: `https://storage.example.com/files/${typia.random<string & tags.Format<"uuid">>()}.pdf`,
    } satisfies IDiscussionBoardArticleFile.ICreate;

    const uploadedFile: IDiscussionBoardArticleFile =
      await api.functional.discussionBoard.member.articles.files.create(
        connection,
        {
          articleId: article.id,
          body: fileData,
        },
      );
    typia.assert(uploadedFile);
    uploadedFiles.push(uploadedFile);
  }

  // Verify all 4 files were uploaded
  TestValidator.equals("uploaded file count", uploadedFiles.length, 4);

  // Step 4: Test min_size filtering (>= 10240 bytes, exclude small files)
  const minSizeFilter = {
    min_size: 10240,
  } satisfies IDiscussionBoardArticleFile.IRequest;

  const minSizeResult: IPageIDiscussionBoardArticleFile.ISummary =
    await api.functional.discussionBoard.articles.files.index(connection, {
      articleId: article.id,
      body: minSizeFilter,
    });
  typia.assert(minSizeResult);

  TestValidator.equals(
    "min_size filter should return 3 files (medium, large, very large)",
    minSizeResult.data.length,
    3,
  );

  for (const file of minSizeResult.data) {
    TestValidator.predicate(
      `file size ${file.size} should be >= 10240`,
      file.size >= 10240,
    );
  }

  // Step 5: Test max_size filtering (<= 102400 bytes, exclude large files)
  const maxSizeFilter = {
    max_size: 102400,
  } satisfies IDiscussionBoardArticleFile.IRequest;

  const maxSizeResult: IPageIDiscussionBoardArticleFile.ISummary =
    await api.functional.discussionBoard.articles.files.index(connection, {
      articleId: article.id,
      body: maxSizeFilter,
    });
  typia.assert(maxSizeResult);

  TestValidator.equals(
    "max_size filter should return 2 files (small, medium)",
    maxSizeResult.data.length,
    2,
  );

  for (const file of maxSizeResult.data) {
    TestValidator.predicate(
      `file size ${file.size} should be <= 102400`,
      file.size <= 102400,
    );
  }

  // Step 6: Test combined range query (10240 <= size <= 102400)
  const rangeFilter = {
    min_size: 10240,
    max_size: 102400,
  } satisfies IDiscussionBoardArticleFile.IRequest;

  const rangeResult: IPageIDiscussionBoardArticleFile.ISummary =
    await api.functional.discussionBoard.articles.files.index(connection, {
      articleId: article.id,
      body: rangeFilter,
    });
  typia.assert(rangeResult);

  TestValidator.equals(
    "range filter should return 1 file (medium only)",
    rangeResult.data.length,
    1,
  );

  for (const file of rangeResult.data) {
    TestValidator.predicate(
      `file size ${file.size} should be >= 10240`,
      file.size >= 10240,
    );
    TestValidator.predicate(
      `file size ${file.size} should be <= 102400`,
      file.size <= 102400,
    );
  }

  // Verify the medium file is in the range result
  const mediumFile = rangeResult.data[0];
  TestValidator.equals("medium file size matches", mediumFile.size, 50000);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleFile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticleFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticleFile";

/**
 * Test filtering file attachments by upload timestamp range using
 * uploaded_after and uploaded_before parameters.
 *
 * This test validates temporal filtering for finding recently uploaded or
 * historical files.
 *
 * Steps:
 *
 * 1. Create a member account for authentication
 * 2. Create an article to attach files to
 * 3. Upload multiple files sequentially to create different upload timestamps
 * 4. Test uploaded_after parameter to retrieve files after a specific timestamp
 * 5. Test uploaded_before parameter to retrieve files before a specific timestamp
 * 6. Test combined time range query with both parameters
 * 7. Validate that returned files have created_at values matching filter criteria
 */
export async function test_api_article_files_filter_by_upload_time_range(
  connection: api.IConnection,
) {
  // 1. Create member account for authentication
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "testPassword123!";
  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      username: RandomGenerator.name(),
      href: "https://test.example.com/register",
      referrer: "https://test.example.com/",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create an article to attach files to
  const article = await api.functional.discussionBoard.articles.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 3 }),
        body: RandomGenerator.content({ paragraphs: 2 }),
      } satisfies IDiscussionBoardArticle.ICreate,
    },
  );
  typia.assert(article);

  // 3. Upload multiple files sequentially to create different upload timestamps
  const uploadedFiles: IDiscussionBoardArticleFile[] = [];
  const fileCount = 5;

  for (let i = 0; i < fileCount; i++) {
    const file =
      await api.functional.discussionBoard.member.articles.files.create(
        connection,
        {
          articleId: article.id,
          body: {
            original_filename: `test-document-${i}.pdf`,
            file_size: typia.random<
              number & tags.Type<"int32"> & tags.Minimum<1>
            >(),
            content_type: "application/pdf",
            storage_url: typia.random<string & tags.Format<"uri">>(),
          } satisfies IDiscussionBoardArticleFile.ICreate,
        },
      );
    typia.assert(file);
    uploadedFiles.push(file);

    // Small delay to ensure different timestamps
    if (i < fileCount - 1) {
      await new Promise((resolve) => setTimeout(resolve, 100));
    }
  }

  // Ensure we have uploaded files for testing
  TestValidator.predicate(
    "should have uploaded multiple files",
    uploadedFiles.length >= 3,
  );

  // 4. Test uploaded_after parameter - get files after the second file's timestamp
  const afterTimestamp = uploadedFiles[1].created_at;
  const filesAfter = await api.functional.discussionBoard.articles.files.index(
    connection,
    {
      articleId: article.id,
      body: {
        uploaded_after: afterTimestamp,
      } satisfies IDiscussionBoardArticleFile.IRequest,
    },
  );
  typia.assert(filesAfter);

  // Validate response structure
  TestValidator.predicate(
    "uploaded_after query should return valid paginated response",
    filesAfter.data !== null && Array.isArray(filesAfter.data),
  );

  // 5. Test uploaded_before parameter - get files before the fourth file's timestamp
  const beforeTimestamp = uploadedFiles[3].created_at;
  const filesBefore = await api.functional.discussionBoard.articles.files.index(
    connection,
    {
      articleId: article.id,
      body: {
        uploaded_before: beforeTimestamp,
      } satisfies IDiscussionBoardArticleFile.IRequest,
    },
  );
  typia.assert(filesBefore);

  // Validate pagination structure
  TestValidator.predicate(
    "uploaded_before query should return valid pagination metadata",
    filesBefore.pagination !== null && filesBefore.pagination !== undefined,
  );

  // 6. Test combined time range query - get files between second and fourth file
  const rangeStart = uploadedFiles[1].created_at;
  const rangeEnd = uploadedFiles[3].created_at;
  const filesInRange =
    await api.functional.discussionBoard.articles.files.index(connection, {
      articleId: article.id,
      body: {
        uploaded_after: rangeStart,
        uploaded_before: rangeEnd,
      } satisfies IDiscussionBoardArticleFile.IRequest,
    });
  typia.assert(filesInRange);

  // 7. Validate time range results
  TestValidator.predicate(
    "time range query should return valid data array",
    Array.isArray(filesInRange.data),
  );

  // Verify pagination info is present
  TestValidator.predicate(
    "time range query should have pagination info",
    filesInRange.pagination !== null &&
      typeof filesInRange.pagination.current === "number",
  );

  // Test edge case: query with very recent timestamp
  const veryRecentTimestamp = new Date().toISOString();
  const recentFiles = await api.functional.discussionBoard.articles.files.index(
    connection,
    {
      articleId: article.id,
      body: {
        uploaded_after: veryRecentTimestamp,
      } satisfies IDiscussionBoardArticleFile.IRequest,
    },
  );
  typia.assert(recentFiles);

  TestValidator.predicate(
    "future timestamp query should return valid response structure",
    Array.isArray(recentFiles.data) && recentFiles.pagination !== null,
  );

  // Verify all files in any result have valid IDs
  for (const fileData of filesInRange.data) {
    TestValidator.predicate(
      "file should have valid UUID identifier",
      typeof fileData.id === "string" && fileData.id.length > 0,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleFile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticleFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticleFile";

/**
 * Test sorting file attachments using multiple sort options.
 *
 * This test validates the file attachment sorting functionality for discussion
 * board articles. It verifies that files can be sorted by different fields
 * (created_at, size, name, extension) in both ascending and descending order.
 *
 * Test workflow:
 *
 * 1. Create a member account for authentication
 * 2. Create an article to attach files to
 * 3. Upload multiple diverse files with varying characteristics
 * 4. Test sorting by created_at in descending order
 * 5. Test sorting by size in ascending order
 * 6. Test sorting by name in ascending and descending order
 * 7. Test sorting by extension to group files by type
 */
export async function test_api_article_files_sorting_options(
  connection: api.IConnection,
) {
  // Step 1: Create member account for authentication
  const memberData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "testPassword123!",
    username: RandomGenerator.name(1),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMember.ICreate;

  const member = await api.functional.auth.member.join(connection, {
    body: memberData,
  });
  typia.assert(member);

  // Step 2: Create an article to attach files to
  const articleData = {
    title: RandomGenerator.paragraph({ sentences: 3, wordMin: 3, wordMax: 7 }),
    body: RandomGenerator.content({
      paragraphs: 2,
      sentenceMin: 5,
      sentenceMax: 10,
    }),
  } satisfies IDiscussionBoardArticle.ICreate;

  const article = await api.functional.discussionBoard.articles.create(
    connection,
    {
      body: articleData,
    },
  );
  typia.assert(article);

  // Step 3: Upload multiple files with varying characteristics
  const fileExtensions = ["pdf", "docx", "txt", "xlsx", "csv"] as const;
  const contentTypes = [
    "application/pdf",
    "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    "text/plain",
    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    "text/csv",
  ] as const;

  const uploadedFiles: IDiscussionBoardArticleFile[] = [];

  for (let i = 0; i < 5; i++) {
    const ext = fileExtensions[i];
    const fileData = {
      original_filename: `${RandomGenerator.alphabets(8)}.${ext}`,
      file_size: typia.random<number & tags.Type<"int32"> & tags.Minimum<1>>(),
      content_type: contentTypes[i],
      storage_url: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardArticleFile.ICreate;

    const uploadedFile =
      await api.functional.discussionBoard.member.articles.files.create(
        connection,
        {
          articleId: article.id,
          body: fileData,
        },
      );
    typia.assert(uploadedFile);
    uploadedFiles.push(uploadedFile);

    await new Promise((resolve) => setTimeout(resolve, 100));
  }

  // Step 4: Test sorting by created_at in descending order (newest first)
  const sortedByDateDesc =
    await api.functional.discussionBoard.articles.files.index(connection, {
      articleId: article.id,
      body: {
        sort_by: "created_at",
        sort_order: "desc",
      } satisfies IDiscussionBoardArticleFile.IRequest,
    });
  typia.assert(sortedByDateDesc);

  TestValidator.predicate(
    "files sorted by created_at descending",
    sortedByDateDesc.data.length === uploadedFiles.length,
  );

  for (let i = 0; i < sortedByDateDesc.data.length - 1; i++) {
    const current = uploadedFiles.find(
      (f) => f.id === sortedByDateDesc.data[i].id,
    );
    const next = uploadedFiles.find(
      (f) => f.id === sortedByDateDesc.data[i + 1].id,
    );

    if (current && next) {
      TestValidator.predicate(
        "created_at descending order verification",
        new Date(current.created_at).getTime() >=
          new Date(next.created_at).getTime(),
      );
    }
  }

  // Step 5: Test sorting by size in ascending order (smallest to largest)
  const sortedBySizeAsc =
    await api.functional.discussionBoard.articles.files.index(connection, {
      articleId: article.id,
      body: {
        sort_by: "size",
        sort_order: "asc",
      } satisfies IDiscussionBoardArticleFile.IRequest,
    });
  typia.assert(sortedBySizeAsc);

  for (let i = 0; i < sortedBySizeAsc.data.length - 1; i++) {
    const currentSize = sortedBySizeAsc.data[i].size;
    const nextSize = sortedBySizeAsc.data[i + 1].size;

    TestValidator.predicate(
      "size ascending order verification",
      currentSize <= nextSize,
    );
  }

  // Step 6: Test sorting by name in ascending order
  const sortedByNameAsc =
    await api.functional.discussionBoard.articles.files.index(connection, {
      articleId: article.id,
      body: {
        sort_by: "name",
        sort_order: "asc",
      } satisfies IDiscussionBoardArticleFile.IRequest,
    });
  typia.assert(sortedByNameAsc);

  for (let i = 0; i < sortedByNameAsc.data.length - 1; i++) {
    const currentName = sortedByNameAsc.data[i].name;
    const nextName = sortedByNameAsc.data[i + 1].name;

    TestValidator.predicate(
      "name ascending order verification",
      currentName.localeCompare(nextName) <= 0,
    );
  }

  // Step 7: Test sorting by name in descending order
  const sortedByNameDesc =
    await api.functional.discussionBoard.articles.files.index(connection, {
      articleId: article.id,
      body: {
        sort_by: "name",
        sort_order: "desc",
      } satisfies IDiscussionBoardArticleFile.IRequest,
    });
  typia.assert(sortedByNameDesc);

  for (let i = 0; i < sortedByNameDesc.data.length - 1; i++) {
    const currentName = sortedByNameDesc.data[i].name;
    const nextName = sortedByNameDesc.data[i + 1].name;

    TestValidator.predicate(
      "name descending order verification",
      currentName.localeCompare(nextName) >= 0,
    );
  }

  // Step 8: Test sorting by extension to group files by type
  const sortedByExtension =
    await api.functional.discussionBoard.articles.files.index(connection, {
      articleId: article.id,
      body: {
        sort_by: "extension",
        sort_order: "asc",
      } satisfies IDiscussionBoardArticleFile.IRequest,
    });
  typia.assert(sortedByExtension);

  for (let i = 0; i < sortedByExtension.data.length - 1; i++) {
    const currentExt = sortedByExtension.data[i].extension;
    const nextExt = sortedByExtension.data[i + 1].extension;

    TestValidator.predicate(
      "extension ascending order verification",
      currentExt.localeCompare(nextExt) <= 0,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleFile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticleFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticleFile";

/**
 * Test soft deletion filtering for article file attachments.
 *
 * This test validates that the file listing API correctly filters soft-deleted
 * files based on the include_deleted parameter. Since the API response returns
 * summary objects without the deleted_at field, we validate soft deletion
 * behavior through:
 *
 * 1. File count differences: include_deleted=false returns fewer files than
 *    include_deleted=true
 * 2. File ID presence: deleted files are absent when include_deleted=false
 * 3. File ID presence: deleted files are present when include_deleted=true
 *
 * Test Flow:
 *
 * 1. Register and authenticate a new member
 * 2. Create a discussion board article
 * 3. Upload 4 file attachments to the article
 * 4. Soft-delete 2 of the 4 files
 * 5. Query files without include_deleted - verify only 2 active files returned
 * 6. Query files with include_deleted=false - verify only 2 active files returned
 * 7. Query files with include_deleted=true - verify all 4 files returned
 * 8. Validate that deleted file IDs are excluded/included appropriately
 */
export async function test_api_article_files_soft_deletion_handling(
  connection: api.IConnection,
) {
  // Step 1: Register and authenticate a new member
  const memberRegistration = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "SecurePassword123!",
    username: RandomGenerator.name(1),
    href: "https://example.com/register",
    referrer: "https://example.com/home",
  } satisfies IDiscussionBoardMember.ICreate;

  const authenticatedMember: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: memberRegistration,
    });
  typia.assert(authenticatedMember);

  // Step 2: Create a discussion board article
  const articleData = {
    title: RandomGenerator.paragraph({ sentences: 1, wordMin: 5, wordMax: 10 }),
    body: RandomGenerator.content({
      paragraphs: 2,
      sentenceMin: 10,
      sentenceMax: 20,
    }),
  } satisfies IDiscussionBoardArticle.ICreate;

  const createdArticle: IDiscussionBoardArticle =
    await api.functional.discussionBoard.articles.create(connection, {
      body: articleData,
    });
  typia.assert(createdArticle);

  // Step 3: Upload 4 file attachments to the article
  const fileAttachments: IDiscussionBoardArticleFile[] =
    await ArrayUtil.asyncRepeat(4, async (index) => {
      const fileData = {
        original_filename: `test-document-${index + 1}.pdf`,
        file_size: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<1>
        >(),
        content_type: "application/pdf",
        storage_url: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardArticleFile.ICreate;

      const uploadedFile: IDiscussionBoardArticleFile =
        await api.functional.discussionBoard.member.articles.files.create(
          connection,
          {
            articleId: createdArticle.id,
            body: fileData,
          },
        );
      typia.assert(uploadedFile);
      return uploadedFile;
    });

  // Step 4: Soft-delete 2 of the 4 files (delete first 2 files)
  const filesToDelete = fileAttachments.slice(0, 2);
  const activeFiles = fileAttachments.slice(2, 4);

  await ArrayUtil.asyncForEach(filesToDelete, async (file) => {
    await api.functional.discussionBoard.member.articles.files.erase(
      connection,
      {
        articleId: createdArticle.id,
        fileId: file.id,
      },
    );
  });

  // Step 5: Query files without include_deleted parameter (defaults to false)
  const defaultQueryResult: IPageIDiscussionBoardArticleFile.ISummary =
    await api.functional.discussionBoard.articles.files.index(connection, {
      articleId: createdArticle.id,
      body: {} satisfies IDiscussionBoardArticleFile.IRequest,
    });
  typia.assert(defaultQueryResult);

  TestValidator.equals(
    "default query should return only active files",
    defaultQueryResult.data.length,
    2,
  );

  // Verify all returned files are active files (by ID matching)
  await ArrayUtil.asyncForEach(defaultQueryResult.data, async (fileSummary) => {
    const matchingActiveFile = activeFiles.find((f) => f.id === fileSummary.id);
    TestValidator.predicate(
      "file from default query should be one of the active files",
      matchingActiveFile !== undefined,
    );
  });

  // Verify deleted files are NOT in the results
  await ArrayUtil.asyncForEach(filesToDelete, async (deletedFile) => {
    const foundInResults = defaultQueryResult.data.find(
      (f) => f.id === deletedFile.id,
    );
    TestValidator.predicate(
      "deleted file should not appear in default query results",
      foundInResults === undefined,
    );
  });

  // Step 6: Query files with include_deleted=false explicitly
  const explicitFalseQueryResult: IPageIDiscussionBoardArticleFile.ISummary =
    await api.functional.discussionBoard.articles.files.index(connection, {
      articleId: createdArticle.id,
      body: {
        include_deleted: false,
      } satisfies IDiscussionBoardArticleFile.IRequest,
    });
  typia.assert(explicitFalseQueryResult);

  TestValidator.equals(
    "explicit false query should return only active files",
    explicitFalseQueryResult.data.length,
    2,
  );

  // Step 7: Query files with include_deleted=true
  const includedDeletedQueryResult: IPageIDiscussionBoardArticleFile.ISummary =
    await api.functional.discussionBoard.articles.files.index(connection, {
      articleId: createdArticle.id,
      body: {
        include_deleted: true,
      } satisfies IDiscussionBoardArticleFile.IRequest,
    });
  typia.assert(includedDeletedQueryResult);

  TestValidator.equals(
    "include_deleted=true query should return all files",
    includedDeletedQueryResult.data.length,
    4,
  );

  // Step 8: Validate that deleted files appear in include_deleted=true results
  await ArrayUtil.asyncForEach(filesToDelete, async (deletedFile) => {
    const foundInResults = includedDeletedQueryResult.data.find(
      (f) => f.id === deletedFile.id,
    );
    TestValidator.predicate(
      "deleted file should appear when include_deleted=true",
      foundInResults !== undefined,
    );
  });

  // Validate that active files appear in include_deleted=true results
  await ArrayUtil.asyncForEach(activeFiles, async (activeFile) => {
    const foundInResults = includedDeletedQueryResult.data.find(
      (f) => f.id === activeFile.id,
    );
    TestValidator.predicate(
      "active file should appear when include_deleted=true",
      foundInResults !== undefined,
    );
  });

  // Verify pagination metadata
  TestValidator.equals(
    "default query pagination should show 2 records",
    defaultQueryResult.pagination.records,
    2,
  );

  TestValidator.equals(
    "include_deleted=true pagination should show 4 records",
    includedDeletedQueryResult.pagination.records,
    4,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleFile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticleFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticleFile";

/**
 * Test combining multiple filter parameters to perform complex file searches.
 *
 * This scenario validates that all filter criteria work together correctly for
 * precise file discovery. Creates an article as a member, uploads a diverse
 * collection of files with varying properties (names, types, sizes,
 * timestamps). Performs complex queries combining multiple filters: search by
 * filename pattern + filter by extension + limit by size range + restrict by
 * upload time range. For example, search for files containing 'report' that are
 * PDF format, between 50KB-500KB size, uploaded in the last month, sorted by
 * size descending. Verifies that all filter conditions are properly ANDed
 * together and results satisfy every specified criterion. Tests various filter
 * combinations to ensure robust multi-criteria search capability.
 */
export async function test_api_article_files_combined_filters(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate a member for testing
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      password: "testPassword123!",
      username: RandomGenerator.name(),
      href: "https://example.com/register",
      referrer: "https://example.com/home",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Step 2: Create an article to attach files to
  const article = await api.functional.discussionBoard.articles.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 3 }),
        body: RandomGenerator.content({ paragraphs: 2 }),
      } satisfies IDiscussionBoardArticle.ICreate,
    },
  );
  typia.assert(article);

  // Step 3: Upload diverse collection of files with varying properties
  const uploadedFiles: IDiscussionBoardArticleFile[] = [];

  // Create files with different characteristics for comprehensive testing
  const fileConfigs = [
    {
      name: "report_summary_2024.pdf",
      extension: "pdf",
      size: 75000,
      contentType: "application/pdf",
    },
    {
      name: "report_analysis.pdf",
      extension: "pdf",
      size: 120000,
      contentType: "application/pdf",
    },
    {
      name: "data_report.xlsx",
      extension: "xlsx",
      size: 250000,
      contentType:
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    },
    {
      name: "document_final.docx",
      extension: "docx",
      size: 85000,
      contentType:
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    },
    {
      name: "summary_notes.txt",
      extension: "txt",
      size: 15000,
      contentType: "text/plain",
    },
    {
      name: "report_quarterly.pdf",
      extension: "pdf",
      size: 450000,
      contentType: "application/pdf",
    },
    {
      name: "data_export.csv",
      extension: "csv",
      size: 30000,
      contentType: "text/csv",
    },
    {
      name: "meeting_notes.txt",
      extension: "txt",
      size: 8000,
      contentType: "text/plain",
    },
    {
      name: "presentation.pdf",
      extension: "pdf",
      size: 600000,
      contentType: "application/pdf",
    },
    {
      name: "budget_report.xlsx",
      extension: "xlsx",
      size: 180000,
      contentType:
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    },
  ];

  for (const config of fileConfigs) {
    await new Promise((resolve) => setTimeout(resolve, 100));

    const file =
      await api.functional.discussionBoard.member.articles.files.create(
        connection,
        {
          articleId: article.id,
          body: {
            original_filename: config.name,
            file_size: config.size,
            content_type: config.contentType,
            storage_url: `https://storage.example.com/files/${typia.random<string & tags.Format<"uuid">>()}.${config.extension}`,
          } satisfies IDiscussionBoardArticleFile.ICreate,
        },
      );
    typia.assert(file);
    uploadedFiles.push(file);
  }

  // Step 4: Test combined filters - filename pattern + extension + size range
  const combinedFilterResult1 =
    await api.functional.discussionBoard.articles.files.index(connection, {
      articleId: article.id,
      body: {
        page: 1,
        limit: 20,
        search: "report",
        extension: "pdf",
        min_size: 50000,
        max_size: 500000,
        sort_by: "size",
        sort_order: "desc",
      } satisfies IDiscussionBoardArticleFile.IRequest,
    });
  typia.assert(combinedFilterResult1);

  // Verify all results match ALL filter criteria
  TestValidator.predicate(
    "combined filter results should not be empty",
    combinedFilterResult1.data.length > 0,
  );

  for (const file of combinedFilterResult1.data) {
    TestValidator.predicate(
      "filename contains search term 'report'",
      file.name.toLowerCase().includes("report"),
    );
    TestValidator.equals("file extension is pdf", file.extension, "pdf");
    TestValidator.predicate(
      "file size is between 50KB and 500KB",
      file.size >= 50000 && file.size <= 500000,
    );
  }

  // Verify sort order (descending by size)
  for (let i = 0; i < combinedFilterResult1.data.length - 1; i++) {
    TestValidator.predicate(
      "files sorted by size descending",
      combinedFilterResult1.data[i].size >=
        combinedFilterResult1.data[i + 1].size,
    );
  }

  // Step 5: Test different filter combination - specific extension + size range
  const combinedFilterResult2 =
    await api.functional.discussionBoard.articles.files.index(connection, {
      articleId: article.id,
      body: {
        page: 1,
        limit: 20,
        extension: "xlsx",
        min_size: 100000,
        max_size: 300000,
        sort_by: "name",
        sort_order: "asc",
      } satisfies IDiscussionBoardArticleFile.IRequest,
    });
  typia.assert(combinedFilterResult2);

  for (const file of combinedFilterResult2.data) {
    TestValidator.equals("file extension is xlsx", file.extension, "xlsx");
    TestValidator.predicate(
      "file size is between 100KB and 300KB",
      file.size >= 100000 && file.size <= 300000,
    );
  }

  // Step 6: Test content type filter with size constraints
  const combinedFilterResult3 =
    await api.functional.discussionBoard.articles.files.index(connection, {
      articleId: article.id,
      body: {
        page: 1,
        limit: 20,
        content_type: "application/pdf",
        min_size: 70000,
        max_size: 200000,
        sort_by: "size",
        sort_order: "asc",
      } satisfies IDiscussionBoardArticleFile.IRequest,
    });
  typia.assert(combinedFilterResult3);

  for (const file of combinedFilterResult3.data) {
    TestValidator.equals(
      "content type is PDF",
      file.content_type,
      "application/pdf",
    );
    TestValidator.predicate(
      "file size is between 70KB and 200KB",
      file.size >= 70000 && file.size <= 200000,
    );
  }

  // Verify ascending sort order
  for (let i = 0; i < combinedFilterResult3.data.length - 1; i++) {
    TestValidator.predicate(
      "files sorted by size ascending",
      combinedFilterResult3.data[i].size <=
        combinedFilterResult3.data[i + 1].size,
    );
  }

  // Step 7: Test search with multiple criteria including name filter
  const combinedFilterResult4 =
    await api.functional.discussionBoard.articles.files.index(connection, {
      articleId: article.id,
      body: {
        page: 1,
        limit: 10,
        name: "data",
        min_size: 20000,
        sort_by: "name",
        sort_order: "asc",
      } satisfies IDiscussionBoardArticleFile.IRequest,
    });
  typia.assert(combinedFilterResult4);

  for (const file of combinedFilterResult4.data) {
    TestValidator.predicate(
      "filename contains 'data'",
      file.name.toLowerCase().includes("data"),
    );
