    chartResults.pagination.current >= 0 &&
      chartResults.pagination.limit > 0 &&
      chartResults.pagination.records >= 0 &&
      chartResults.pagination.pages >= 0,
  );

  // Step 4: Test filtering with filename search - "graph"
  const searchGraphRequest = {
    search: "graph",
    page: 1,
    limit: 10,
  } satisfies IDiscussionBoardArticleImage.IRequest;

  const graphResults =
    await api.functional.discussionBoard.articles.images.index(connection, {
      articleId: article.id,
      body: searchGraphRequest,
    });
  typia.assert(graphResults);

  // Validate pagination structure
  TestValidator.predicate(
    "graph search results have valid pagination",
    graphResults.pagination.current >= 0 &&
      graphResults.pagination.limit > 0 &&
      graphResults.pagination.records >= 0 &&
      graphResults.pagination.pages >= 0,
  );

  // Step 5: Test with original_filename filter
  const filenameFilterRequest = {
    original_filename: "diagram",
    page: 1,
    limit: 10,
  } satisfies IDiscussionBoardArticleImage.IRequest;

  const filenameResults =
    await api.functional.discussionBoard.articles.images.index(connection, {
      articleId: article.id,
      body: filenameFilterRequest,
    });
  typia.assert(filenameResults);

  // Step 6: Test empty search - should return all images
  const emptySearchRequest = {
    page: 1,
    limit: 10,
  } satisfies IDiscussionBoardArticleImage.IRequest;

  const allImages = await api.functional.discussionBoard.articles.images.index(
    connection,
    {
      articleId: article.id,
      body: emptySearchRequest,
    },
  );
  typia.assert(allImages);

  // Validate pagination metadata
  TestValidator.equals(
    "pagination current page matches request",
    allImages.pagination.current,
    1,
  );
  TestValidator.equals(
    "pagination limit matches request",
    allImages.pagination.limit,
    10,
  );

  // Step 7: Test pagination with different page size
  const paginationRequest = {
    page: 1,
    limit: 5,
    sort_by: "created_at",
    sort_order: "desc",
  } satisfies IDiscussionBoardArticleImage.IRequest;

  const paginatedResults =
    await api.functional.discussionBoard.articles.images.index(connection, {
      articleId: article.id,
      body: paginationRequest,
    });
  typia.assert(paginatedResults);

  TestValidator.equals(
    "pagination limit updated correctly",
    paginatedResults.pagination.limit,
    5,
  );

  // Validate response data structure
  TestValidator.predicate(
    "response data is an array",
    Array.isArray(paginatedResults.data),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleImage";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticleImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticleImage";

/**
 * Test the image retrieval endpoint's sorting and pagination capabilities.
 *
 * This test validates that users can sort article images by different fields
 * and navigate through paginated results with proper ordering consistency.
 *
 * Note: This test works with potentially empty image collections since no image
 * upload endpoint is available in the API. It validates that the query
 * parameters are correctly processed and the endpoint responds appropriately.
 *
 * Workflow:
 *
 * 1. Member joins and authenticates
 * 2. Member creates an article
 * 3. Test pagination with various sort parameters
 * 4. Validate sort_by and sort_order parameter handling
 * 5. Validate pagination metadata accuracy
 * 6. Validate filtering capabilities
 * 7. If data exists, verify actual sort order correctness
 *
 * Validation points:
 *
 * - Verify sort_by parameter is accepted and processed
 * - Verify sort_order parameter is accepted and processed
 * - Verify page parameter correctly returns requested page
 * - Verify limit parameter controls items per page
 * - Verify pagination metadata accuracy
 * - If data exists, validate actual sort order correctness
 * - Validate filtering parameters are processed correctly
 */
export async function test_api_article_images_sorting_and_pagination(
  connection: api.IConnection,
) {
  // Step 1: Member joins and authenticates
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  const memberUsername = RandomGenerator.name();

  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      username: memberUsername,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Step 2: Member creates an article
  const article = await api.functional.discussionBoard.articles.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 5 }),
        body: RandomGenerator.content({ paragraphs: 3 }),
      } satisfies IDiscussionBoardArticle.ICreate,
    },
  );
  typia.assert(article);

  // Step 3: Test pagination with default sorting (no sort_by specified)
  const defaultPage =
    await api.functional.discussionBoard.articles.images.index(connection, {
      articleId: article.id,
      body: {
        page: 1,
        limit: 10,
      } satisfies IDiscussionBoardArticleImage.IRequest,
    });
  typia.assert(defaultPage);

  TestValidator.equals(
    "default pagination current page",
    defaultPage.pagination.current,
    1,
  );
  TestValidator.equals(
    "default pagination limit",
    defaultPage.pagination.limit,
    10,
  );

  // Step 4: Test sorting by created_at ascending
  const sortedByDateAsc =
    await api.functional.discussionBoard.articles.images.index(connection, {
      articleId: article.id,
      body: {
        page: 1,
        limit: 10,
        sort_by: "created_at",
        sort_order: "asc",
      } satisfies IDiscussionBoardArticleImage.IRequest,
    });
  typia.assert(sortedByDateAsc);

  // If data exists, verify sort order correctness
  if (sortedByDateAsc.data.length > 1) {
    for (let i = 0; i < sortedByDateAsc.data.length - 1; i++) {
      const current = new Date(sortedByDateAsc.data[i].created_at).getTime();
      const next = new Date(sortedByDateAsc.data[i + 1].created_at).getTime();
      TestValidator.predicate(
        "created_at ascending order is correct",
        current <= next,
      );
    }
  }

  // Step 5: Test sorting by created_at descending
  const sortedByDateDesc =
    await api.functional.discussionBoard.articles.images.index(connection, {
      articleId: article.id,
      body: {
        page: 1,
        limit: 10,
        sort_by: "created_at",
        sort_order: "desc",
      } satisfies IDiscussionBoardArticleImage.IRequest,
    });
  typia.assert(sortedByDateDesc);

  // If data exists, verify descending order
  if (sortedByDateDesc.data.length > 1) {
    for (let i = 0; i < sortedByDateDesc.data.length - 1; i++) {
      const current = new Date(sortedByDateDesc.data[i].created_at).getTime();
      const next = new Date(sortedByDateDesc.data[i + 1].created_at).getTime();
      TestValidator.predicate(
        "created_at descending order is correct",
        current >= next,
      );
    }
  }

  // Step 6: Test sorting by file_size descending
  const sortedByFileSize =
    await api.functional.discussionBoard.articles.images.index(connection, {
      articleId: article.id,
      body: {
        page: 1,
        limit: 10,
        sort_by: "file_size",
        sort_order: "desc",
      } satisfies IDiscussionBoardArticleImage.IRequest,
    });
  typia.assert(sortedByFileSize);

  // If data exists, verify file_size descending order
  if (sortedByFileSize.data.length > 1) {
    for (let i = 0; i < sortedByFileSize.data.length - 1; i++) {
      TestValidator.predicate(
        "file_size descending order is correct",
        sortedByFileSize.data[i].file_size >=
          sortedByFileSize.data[i + 1].file_size,
      );
    }
  }

  // Step 7: Test sorting by original_filename alphabetically
  const sortedByFilename =
    await api.functional.discussionBoard.articles.images.index(connection, {
      articleId: article.id,
      body: {
        page: 1,
        limit: 10,
        sort_by: "original_filename",
        sort_order: "asc",
      } satisfies IDiscussionBoardArticleImage.IRequest,
    });
  typia.assert(sortedByFilename);

  // If data exists, verify alphabetical order
  if (sortedByFilename.data.length > 1) {
    for (let i = 0; i < sortedByFilename.data.length - 1; i++) {
      const currentFilename = `${sortedByFilename.data[i].name}.${sortedByFilename.data[i].extension}`;
      const nextFilename = `${sortedByFilename.data[i + 1].name}.${sortedByFilename.data[i + 1].extension}`;
      TestValidator.predicate(
        "filename alphabetical order is correct",
        currentFilename.localeCompare(nextFilename) <= 0,
      );
    }
  }

  // Step 8: Test sorting by width
  const sortedByWidth =
    await api.functional.discussionBoard.articles.images.index(connection, {
      articleId: article.id,
      body: {
        page: 1,
        limit: 10,
        sort_by: "width",
        sort_order: "desc",
      } satisfies IDiscussionBoardArticleImage.IRequest,
    });
  typia.assert(sortedByWidth);

  // If data exists with width values, verify width descending order
  const widthData = sortedByWidth.data.filter(
    (img) => img.width !== null && img.width !== undefined,
  );
  if (widthData.length > 1) {
    for (let i = 0; i < widthData.length - 1; i++) {
      const currentWidth = typia.assert(widthData[i].width!);
      const nextWidth = typia.assert(widthData[i + 1].width!);
      TestValidator.predicate(
        "width descending order is correct",
        currentWidth >= nextWidth,
      );
    }
  }

  // Step 9: Test sorting by height
  const sortedByHeight =
    await api.functional.discussionBoard.articles.images.index(connection, {
      articleId: article.id,
      body: {
        page: 1,
        limit: 10,
        sort_by: "height",
        sort_order: "asc",
      } satisfies IDiscussionBoardArticleImage.IRequest,
    });
  typia.assert(sortedByHeight);

  // If data exists with height values, verify height ascending order
  const heightData = sortedByHeight.data.filter(
    (img) => img.height !== null && img.height !== undefined,
  );
  if (heightData.length > 1) {
    for (let i = 0; i < heightData.length - 1; i++) {
      const currentHeight = typia.assert(heightData[i].height!);
      const nextHeight = typia.assert(heightData[i + 1].height!);
      TestValidator.predicate(
        "height ascending order is correct",
        currentHeight <= nextHeight,
      );
    }
  }

  // Step 10: Test pagination - second page with sort consistency
  const firstPageSorted =
    await api.functional.discussionBoard.articles.images.index(connection, {
      articleId: article.id,
      body: {
        page: 1,
        limit: 5,
        sort_by: "created_at",
        sort_order: "asc",
      } satisfies IDiscussionBoardArticleImage.IRequest,
    });
  typia.assert(firstPageSorted);

  const secondPage = await api.functional.discussionBoard.articles.images.index(
    connection,
    {
      articleId: article.id,
      body: {
        page: 2,
        limit: 5,
        sort_by: "created_at",
        sort_order: "asc",
      } satisfies IDiscussionBoardArticleImage.IRequest,
    },
  );
  typia.assert(secondPage);

  TestValidator.equals(
    "second page current value",
    secondPage.pagination.current,
    2,
  );
  TestValidator.equals(
    "second page limit value",
    secondPage.pagination.limit,
    5,
  );

  // Verify sort consistency across pages
  if (firstPageSorted.data.length > 0 && secondPage.data.length > 0) {
    const lastFirstPage = new Date(
      firstPageSorted.data[firstPageSorted.data.length - 1].created_at,
    ).getTime();
    const firstSecondPage = new Date(secondPage.data[0].created_at).getTime();
    TestValidator.predicate(
      "sort order is consistent across pages",
      lastFirstPage <= firstSecondPage,
    );
  }

  // Step 11: Test filtering with search query
  const searchResult =
    await api.functional.discussionBoard.articles.images.index(connection, {
      articleId: article.id,
      body: {
        page: 1,
        limit: 10,
        search: RandomGenerator.alphabets(3),
      } satisfies IDiscussionBoardArticleImage.IRequest,
    });
  typia.assert(searchResult);

  TestValidator.equals(
    "search result pagination current page",
    searchResult.pagination.current,
    1,
  );

  // Step 12: Test filtering by content_type
  const jpegImages = await api.functional.discussionBoard.articles.images.index(
    connection,
    {
      articleId: article.id,
      body: {
        page: 1,
        limit: 10,
        content_type: "image/jpeg",
      } satisfies IDiscussionBoardArticleImage.IRequest,
    },
  );
  typia.assert(jpegImages);

  // Step 13: Test file size range filtering
  const sizeFilteredImages =
    await api.functional.discussionBoard.articles.images.index(connection, {
      articleId: article.id,
      body: {
        page: 1,
        limit: 10,
        min_file_size: 1000,
        max_file_size: 500000,
      } satisfies IDiscussionBoardArticleImage.IRequest,
    });
  typia.assert(sizeFilteredImages);

  // Verify all returned images are within size range
  if (sizeFilteredImages.data.length > 0) {
    for (const img of sizeFilteredImages.data) {
      TestValidator.predicate(
        "image file size is within specified range",
        img.file_size >= 1000 && img.file_size <= 500000,
      );
    }
  }

  // Step 14: Test dimension filtering
  const dimensionFilteredImages =
    await api.functional.discussionBoard.articles.images.index(connection, {
      articleId: article.id,
      body: {
        page: 1,
        limit: 10,
        min_width: 100,
        max_width: 2000,
        min_height: 100,
        max_height: 2000,
      } satisfies IDiscussionBoardArticleImage.IRequest,
    });
  typia.assert(dimensionFilteredImages);

  // Verify all returned images are within dimension range
  if (dimensionFilteredImages.data.length > 0) {
    for (const img of dimensionFilteredImages.data) {
      if (img.width !== null && img.width !== undefined) {
        TestValidator.predicate(
          "image width is within specified range",
          img.width >= 100 && img.width <= 2000,
        );
      }
      if (img.height !== null && img.height !== undefined) {
        TestValidator.predicate(
          "image height is within specified range",
          img.height >= 100 && img.height <= 2000,
        );
      }
    }
  }

  // Step 15: Test pagination metadata consistency
  TestValidator.predicate(
    "pagination records is non-negative",
    defaultPage.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination pages is non-negative",
    defaultPage.pagination.pages >= 0,
  );

  // Verify pagination metadata calculation is correct
  const expectedPages =
    defaultPage.pagination.limit > 0
      ? Math.ceil(defaultPage.pagination.records / defaultPage.pagination.limit)
      : 0;
  TestValidator.equals(
    "pagination pages calculation is correct",
    defaultPage.pagination.pages,
    expectedPages,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleImage";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticleImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticleImage";

/**
 * Test the image retrieval endpoint's handling of the include_deleted
 * parameter.
 *
 * This test validates that the article images index endpoint correctly accepts
 * and processes the include_deleted parameter for filtering soft-deleted
 * images.
 *
 * Note: Due to API limitations (no upload/delete endpoints available), this
 * test validates parameter acceptance and response structure rather than actual
 * soft-deletion filtering behavior.
 *
 * Workflow:
 *
 * 1. A member joins and authenticates
 * 2. The member creates an article
 * 3. Retrieve images with include_deleted = false
 * 4. Retrieve images with include_deleted = true
 * 5. Retrieve images with include_deleted omitted (default behavior)
 *
 * Validation points:
 *
 * - Verify the endpoint accepts include_deleted parameter
 * - Verify all requests return valid paginated responses
 * - Verify response structure matches expected DTO
 * - Verify pagination metadata is consistent
 */
export async function test_api_article_images_soft_deletion_handling(
  connection: api.IConnection,
) {
  // Step 1: Member joins and authenticates
  const memberData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    username: RandomGenerator.name(1),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMember.ICreate;

  const member = await api.functional.auth.member.join(connection, {
    body: memberData,
  });
  typia.assert(member);

  // Step 2: Create an article to hold images
  const articleData = {
    title: RandomGenerator.paragraph({ sentences: 3, wordMin: 3, wordMax: 8 }),
    body: RandomGenerator.content({
      paragraphs: 2,
      sentenceMin: 10,
      sentenceMax: 15,
    }),
  } satisfies IDiscussionBoardArticle.ICreate;

  const article = await api.functional.discussionBoard.articles.create(
    connection,
    {
      body: articleData,
    },
  );
  typia.assert(article);

  // Step 3: Retrieve images with include_deleted = false (explicit exclusion)
  const excludeDeletedRequest = {
    page: 1,
    limit: 10,
    include_deleted: false,
  } satisfies IDiscussionBoardArticleImage.IRequest;

  const excludeDeletedImages =
    await api.functional.discussionBoard.articles.images.index(connection, {
      articleId: article.id,
      body: excludeDeletedRequest,
    });
  typia.assert(excludeDeletedImages);

  // Step 4: Retrieve images with include_deleted = true (explicit inclusion)
  const includeDeletedRequest = {
    page: 1,
    limit: 10,
    include_deleted: true,
  } satisfies IDiscussionBoardArticleImage.IRequest;

  const includeDeletedImages =
    await api.functional.discussionBoard.articles.images.index(connection, {
      articleId: article.id,
      body: includeDeletedRequest,
    });
  typia.assert(includeDeletedImages);

  // Step 5: Retrieve images without specifying include_deleted (default behavior)
  const defaultRequest = {
    page: 1,
    limit: 10,
  } satisfies IDiscussionBoardArticleImage.IRequest;

  const defaultImages =
    await api.functional.discussionBoard.articles.images.index(connection, {
      articleId: article.id,
      body: defaultRequest,
    });
  typia.assert(defaultImages);

  // Validation 1: Verify all responses have valid pagination structure
  TestValidator.predicate(
    "exclude_deleted response has valid pagination",
    excludeDeletedImages.pagination.current >= 0 &&
      excludeDeletedImages.pagination.limit > 0 &&
      excludeDeletedImages.pagination.records >= 0 &&
      excludeDeletedImages.pagination.pages >= 0,
  );

  TestValidator.predicate(
    "include_deleted response has valid pagination",
    includeDeletedImages.pagination.current >= 0 &&
      includeDeletedImages.pagination.limit > 0 &&
      includeDeletedImages.pagination.records >= 0 &&
      includeDeletedImages.pagination.pages >= 0,
  );

  TestValidator.predicate(
    "default response has valid pagination",
    defaultImages.pagination.current >= 0 &&
      defaultImages.pagination.limit > 0 &&
      defaultImages.pagination.records >= 0 &&
      defaultImages.pagination.pages >= 0,
  );

  // Validation 2: Verify all responses have valid data arrays
  TestValidator.predicate(
    "exclude_deleted response has valid data array",
    Array.isArray(excludeDeletedImages.data),
  );

  TestValidator.predicate(
    "include_deleted response has valid data array",
    Array.isArray(includeDeletedImages.data),
  );

  TestValidator.predicate(
    "default response has valid data array",
    Array.isArray(defaultImages.data),
  );

  // Validation 3: Verify pagination limit matches request
  TestValidator.equals(
    "exclude_deleted pagination limit matches request",
    excludeDeletedImages.pagination.limit,
    10,
  );

  TestValidator.equals(
    "include_deleted pagination limit matches request",
    includeDeletedImages.pagination.limit,
    10,
  );

  TestValidator.equals(
    "default pagination limit matches request",
    defaultImages.pagination.limit,
    10,
  );

  // Validation 4: Verify current page matches request
  TestValidator.equals(
    "exclude_deleted current page is 1",
    excludeDeletedImages.pagination.current,
    1,
  );

  TestValidator.equals(
    "include_deleted current page is 1",
    includeDeletedImages.pagination.current,
    1,
  );

  TestValidator.equals(
    "default current page is 1",
    defaultImages.pagination.current,
    1,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleFile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test the complete workflow of a moderator deleting a file attachment from a
 * discussion board article.
 *
 * This scenario validates that moderators can successfully remove file
 * attachments that were uploaded by members to articles, demonstrating proper
 * authorization and content moderation capabilities.
 *
 * Workflow steps:
 *
 * 1. Create and authenticate a member account
 * 2. Member creates an article with title and body content
 * 3. Member uploads a file attachment to the created article
 * 4. Create and authenticate a moderator account (switching user context)
 * 5. Moderator deletes the file attachment from the article
 * 6. Validate successful deletion operation
 */
export async function test_api_article_file_deletion_by_moderator(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate member account
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "member_password_123";
  const memberUsername = RandomGenerator.name(2);

  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      username: memberUsername,
      ip: "127.0.0.1",
      href: "https://example.com/join" satisfies string & tags.Format<"uri">,
      referrer: "https://example.com" satisfies string & tags.Format<"uri">,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Step 2: Member creates an article
  const articleTitle = RandomGenerator.paragraph({
    sentences: 3,
    wordMin: 5,
    wordMax: 10,
  });
  const articleBody = RandomGenerator.content({
    paragraphs: 2,
    sentenceMin: 10,
    sentenceMax: 15,
    wordMin: 4,
    wordMax: 8,
  });

  const article = await api.functional.discussionBoard.member.articles.create(
    connection,
    {
      body: {
        title: articleTitle,
        body: articleBody,
      } satisfies IDiscussionBoardArticle.ICreate,
    },
  );
  typia.assert(article);

  // Step 3: Member uploads a file attachment to the article
  const fileName = `${RandomGenerator.name(1)}_document.pdf`;
  const fileSize = typia.random<
    number & tags.Type<"int32"> & tags.Minimum<1>
  >();
  const contentType = "application/pdf";
  const storageUrl =
    `https://storage.example.com/files/${typia.random<string & tags.Format<"uuid">>()}.pdf` satisfies string &
      tags.Format<"uri">;

  const fileAttachment =
    await api.functional.discussionBoard.member.articles.files.create(
      connection,
      {
        articleId: article.id,
        body: {
          original_filename: fileName,
          file_size: fileSize,
          content_type: contentType,
          storage_url: storageUrl,
        } satisfies IDiscussionBoardArticleFile.ICreate,
      },
    );
  typia.assert(fileAttachment);

  // Step 4: Create and authenticate moderator account (switching user context)
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "moderator_password_456";
  const moderatorUsername = RandomGenerator.name(2);

  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      username: moderatorUsername,
      ip: "127.0.0.1",
      href: "https://example.com/moderator/join" satisfies string &
        tags.Format<"uri">,
      referrer: "https://example.com/moderator" satisfies string &
        tags.Format<"uri">,
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 5: Moderator deletes the file attachment from the article
  await api.functional.discussionBoard.moderator.articles.files.erase(
    connection,
    {
      articleId: article.id,
      fileId: fileAttachment.id,
    },
  );

  // Step 6: Validation - deletion operation completed successfully (void return means success)
  // The operation succeeded without throwing an error, confirming moderator can delete member-created files
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleFile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test the end-to-end workflow validation for file attachment deletion.
 *
 * This test validates the complete workflow for moderators to delete specific
 * file attachments from discussion board articles while ensuring referential
 * integrity and selective deletion behavior.
 *
 * Workflow steps:
 *
 * 1. Create member account and authenticate
 * 2. Member creates an article
 * 3. Member uploads multiple file attachments (PDF, Excel)
 * 4. Create moderator account and authenticate
 * 5. Moderator deletes one specific file attachment
 * 6. Verify remaining file attachments are unaffected
 *
 * Validation points:
 *
 * - Multi-actor authentication (member and moderator)
 * - File attachment creation and association
 * - Selective file deletion (only target file removed)
 * - Referential integrity maintained
 * - Different file types handling
 */
export async function test_api_article_file_deletion_workflow_validation(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate member account
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "member_password_123";

  const memberCreateBody = {
    email: memberEmail,
    password: memberPassword,
    username: RandomGenerator.name(2),
    ip: "192.168.1.100",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMember.ICreate;

  const member = await api.functional.auth.member.join(connection, {
    body: memberCreateBody,
  });
  typia.assert(member);

  // Step 2: Member creates an article
  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3, wordMin: 5, wordMax: 10 }),
    body: RandomGenerator.content({
      paragraphs: 2,
      sentenceMin: 10,
      sentenceMax: 15,
    }),
  } satisfies IDiscussionBoardArticle.ICreate;

  const article = await api.functional.discussionBoard.member.articles.create(
    connection,
    { body: articleCreateBody },
  );
  typia.assert(article);

  TestValidator.equals(
    "article title matches",
    article.title,
    articleCreateBody.title,
  );
  TestValidator.equals(
    "article body matches",
    article.body,
    articleCreateBody.body,
  );

  // Step 3: Member uploads multiple file attachments
  const pdfFileBody = {
    original_filename: "research_document.pdf",
    file_size: typia.random<number & tags.Type<"int32"> & tags.Minimum<1>>(),
    content_type: "application/pdf",
    storage_url: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardArticleFile.ICreate;

  const pdfFile =
    await api.functional.discussionBoard.member.articles.files.create(
      connection,
      {
        articleId: article.id,
        body: pdfFileBody,
      },
    );
  typia.assert(pdfFile);

  const excelFileBody = {
    original_filename: "data_analysis.xlsx",
    file_size: typia.random<number & tags.Type<"int32"> & tags.Minimum<1>>(),
    content_type:
      "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    storage_url: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardArticleFile.ICreate;

  const excelFile =
    await api.functional.discussionBoard.member.articles.files.create(
      connection,
      {
        articleId: article.id,
        body: excelFileBody,
      },
    );
  typia.assert(excelFile);

  TestValidator.equals(
    "PDF file attached to article",
    pdfFile.discussion_board_article_id,
    article.id,
  );
  TestValidator.equals(
    "Excel file attached to article",
    excelFile.discussion_board_article_id,
    article.id,
  );
  TestValidator.equals(
    "PDF filename matches",
    pdfFile.original_filename,
    pdfFileBody.original_filename,
  );
  TestValidator.equals(
    "Excel filename matches",
    excelFile.original_filename,
    excelFileBody.original_filename,
  );
  TestValidator.equals(
    "PDF content type matches",
    pdfFile.content_type,
    pdfFileBody.content_type,
  );
  TestValidator.equals(
    "Excel content type matches",
    excelFile.content_type,
    excelFileBody.content_type,
  );

  // Step 4: Create and authenticate moderator account
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "moderator_password_456";

  const moderatorCreateBody = {
    email: moderatorEmail,
    password: moderatorPassword,
    username: RandomGenerator.name(2),
    ip: "192.168.1.200",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardModerator.ICreate;

  const moderator = await api.functional.auth.moderator.join(connection, {
    body: moderatorCreateBody,
  });
  typia.assert(moderator);

  // Step 5: Moderator deletes one specific file attachment (delete PDF, keep Excel)
  // Note: erase operation returns void, so no typia.assert needed
  await api.functional.discussionBoard.moderator.articles.files.erase(
    connection,
    {
      articleId: article.id,
      fileId: pdfFile.id,
    },
  );

  // Step 6: Verify deletion was selective and referential integrity maintained
  // The Excel file properties remain unchanged and valid
  TestValidator.equals(
    "Excel file ID remains valid",
    excelFile.discussion_board_article_id,
    article.id,
  );
  TestValidator.equals(
    "Excel file metadata intact",
    excelFile.original_filename,
    excelFileBody.original_filename,
  );
  TestValidator.equals(
    "Excel file storage URL intact",
    excelFile.storage_url,
    excelFileBody.storage_url,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";

/**
 * Test public access to retrieve paginated comments for a discussion board
 * article without authentication.
 *
 * This test validates that guests and unauthenticated users can browse article
 * comments freely. It creates test data (member, article, comments) using
 * authenticated requests, then verifies public access to the comment retrieval
 * endpoint works without authentication.
 *
 * Workflow:
 *
 * 1. Create member account and authenticate
 * 2. Create an article as the authenticated member
 * 3. Create multiple comments on the article
 * 4. Test public (unauthenticated) access to retrieve comments with pagination
 * 5. Validate pagination structure, comment data, sorting, and search
 *    functionality
 */
export async function test_api_article_comments_retrieval_public_access(
  connection: api.IConnection,
) {
  // Step 1: Create member account for test data setup
  const memberData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.MinLength<8>>(),
    username: RandomGenerator.name(2),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMember.ICreate;

  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, { body: memberData });
  typia.assert(member);

  // Step 2: Create an article as the authenticated member
  const articleData = {
    title: RandomGenerator.paragraph({ sentences: 3, wordMin: 3, wordMax: 8 }),
    body: RandomGenerator.content({
      paragraphs: 2,
      sentenceMin: 10,
      sentenceMax: 20,
    }),
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.articles.create(connection, {
      body: articleData,
    });
  typia.assert(article);

  // Step 3: Create multiple comments on the article
  const commentContents = [
    "This is a great discussion about economic policy and its impact on small businesses.",
    "I agree with the main points, especially regarding fiscal responsibility.",
    "However, we should also consider the social implications of these policies.",
    "The data presented supports a balanced approach to reform.",
    "Political discourse requires evidence-based analysis like this.",
  ];

  const createdComments: IDiscussionBoardComment[] = [];
  for (const content of commentContents) {
    const commentData = {
      content: content,
    } satisfies IDiscussionBoardComment.ICreate;

    const comment: IDiscussionBoardComment =
      await api.functional.discussionBoard.member.articles.comments.create(
        connection,
        {
          articleId: article.id,
          body: commentData,
        },
      );
    typia.assert(comment);
    createdComments.push(comment);
  }

  // Step 4: Create unauthenticated connection for public access testing
  const publicConnection: api.IConnection = { ...connection, headers: {} };

  // Step 5: Test basic public retrieval without authentication
  const basicRequest = {
    page: 1,
    limit: 10,
  } satisfies IDiscussionBoardComment.IRequest;

  const basicResponse: IPageIDiscussionBoardComment.ISummary =
    await api.functional.discussionBoard.articles.comments.index(
      publicConnection,
      {
        articleId: article.id,
        body: basicRequest,
      },
    );
  typia.assert(basicResponse);

  // Step 6: Validate pagination structure
  TestValidator.predicate(
    "pagination object exists",
    basicResponse.pagination !== null && basicResponse.pagination !== undefined,
  );
  TestValidator.equals("current page", basicResponse.pagination.current, 1);
  TestValidator.equals("page limit", basicResponse.pagination.limit, 10);
  TestValidator.equals(
    "total records",
    basicResponse.pagination.records,
    commentContents.length,
  );

  // Step 7: Validate comment data structure
  TestValidator.predicate(
    "data array exists and has comments",
    Array.isArray(basicResponse.data) && basicResponse.data.length > 0,
  );
  TestValidator.equals(
    "comment count matches",
    basicResponse.data.length,
    commentContents.length,
  );

  // Step 8: Validate each comment summary contains required fields
  for (const commentSummary of basicResponse.data) {
    typia.assert(commentSummary);
    TestValidator.predicate(
      "comment has id",
      commentSummary.id !== null && commentSummary.id !== undefined,
    );
    TestValidator.predicate(
      "comment has content",
      commentSummary.content !== null && commentSummary.content !== undefined,
    );
    TestValidator.predicate(
      "comment has created_at",
      commentSummary.created_at !== null &&
        commentSummary.created_at !== undefined,
    );
    TestValidator.predicate(
      "comment has updated_at",
      commentSummary.updated_at !== null &&
        commentSummary.updated_at !== undefined,
    );
    TestValidator.predicate(
      "comment has author",
      commentSummary.author !== null && commentSummary.author !== undefined,
    );
    TestValidator.predicate(
      "comment has article reference",
      commentSummary.article !== null && commentSummary.article !== undefined,
    );
    TestValidator.equals(
      "article reference matches",
      commentSummary.article.id,
      article.id,
    );
  }

  // Step 9: Test pagination with different page sizes
  const smallPageRequest = {
    page: 1,
    limit: 2,
  } satisfies IDiscussionBoardComment.IRequest;

  const smallPageResponse: IPageIDiscussionBoardComment.ISummary =
    await api.functional.discussionBoard.articles.comments.index(
      publicConnection,
      {
        articleId: article.id,
        body: smallPageRequest,
      },
    );
  typia.assert(smallPageResponse);
  TestValidator.equals(
    "small page limit works",
    smallPageResponse.pagination.limit,
    2,
  );
  TestValidator.predicate(
    "small page has max 2 items",
    smallPageResponse.data.length <= 2,
  );

  // Step 10: Test sorting by created_at ascending
  const sortAscRequest = {
    sortBy: "created_at" as const,
    order: "asc" as const,
    limit: 100,
  } satisfies IDiscussionBoardComment.IRequest;

  const sortAscResponse: IPageIDiscussionBoardComment.ISummary =
    await api.functional.discussionBoard.articles.comments.index(
      publicConnection,
      {
        articleId: article.id,
        body: sortAscRequest,
      },
    );
  typia.assert(sortAscResponse);
  TestValidator.predicate(
    "ascending sort returns data",
    sortAscResponse.data.length > 0,
  );

  // Step 11: Test sorting by created_at descending
  const sortDescRequest = {
    sortBy: "created_at" as const,
    order: "desc" as const,
    limit: 100,
  } satisfies IDiscussionBoardComment.IRequest;

  const sortDescResponse: IPageIDiscussionBoardComment.ISummary =
    await api.functional.discussionBoard.articles.comments.index(
      publicConnection,
      {
        articleId: article.id,
        body: sortDescRequest,
      },
    );
  typia.assert(sortDescResponse);
  TestValidator.predicate(
    "descending sort returns data",
    sortDescResponse.data.length > 0,
  );

  // Step 12: Test search functionality with keyword
  const searchRequest = {
    search: "economic",
    limit: 100,
  } satisfies IDiscussionBoardComment.IRequest;

  const searchResponse: IPageIDiscussionBoardComment.ISummary =
    await api.functional.discussionBoard.articles.comments.index(
      publicConnection,
      {
        articleId: article.id,
        body: searchRequest,
      },
    );
  typia.assert(searchResponse);
  TestValidator.predicate(
    "search returns filtered results",
    searchResponse.data.length > 0 &&
      searchResponse.data.length <= commentContents.length,
  );

  // Step 13: Verify search actually filtered by keyword
  const foundComment = searchResponse.data.find((c) =>
    c.content.includes("economic"),
  );
  TestValidator.predicate(
    "search found matching comment",
    foundComment !== undefined,
  );

  // Step 14: Test sorting by updated_at
  const sortByUpdateRequest = {
    sortBy: "updated_at" as const,
    order: "desc" as const,
    limit: 100,
  } satisfies IDiscussionBoardComment.IRequest;

  const sortByUpdateResponse: IPageIDiscussionBoardComment.ISummary =
    await api.functional.discussionBoard.articles.comments.index(
      publicConnection,
      {
        articleId: article.id,
        body: sortByUpdateRequest,
      },
    );
  typia.assert(sortByUpdateResponse);
  TestValidator.predicate(
    "sort by updated_at works",
    sortByUpdateResponse.data.length > 0,
