import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardArticleImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleImage";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function deleteDiscussionBoardModeratorArticlesArticleIdImagesImageId(props: {
  moderator: ModeratorPayload;
  articleId: string & tags.Format<"uuid">;
  imageId: string & tags.Format<"uuid">;
}): Promise<IDiscussionBoardArticleImage> {
  const existingImage =
    await MyGlobal.prisma.discussion_board_article_images.findUnique({
      where: { id: props.imageId },
    });

  if (!existingImage) {
    throw new HttpException("Image not found", 404);
  }

  if (existingImage.discussion_board_article_id !== props.articleId) {
    throw new HttpException(
      "Image does not belong to the specified article",
      400,
    );
  }

  if (existingImage.deleted_at !== null) {
    throw new HttpException("Image has already been deleted", 400);
  }

  const deletedImage =
    await MyGlobal.prisma.discussion_board_article_images.update({
      where: { id: props.imageId },
      data: {
        deleted_at: new Date(),
      },
    });

  return {
    id: deletedImage.id,
    discussion_board_article_id: deletedImage.discussion_board_article_id,
    original_filename: deletedImage.original_filename,
    file_size: deletedImage.file_size,
    content_type: deletedImage.content_type,
    storage_url: deletedImage.storage_url,
    width: deletedImage.width ?? undefined,
    height: deletedImage.height ?? undefined,
    created_at: toISOStringSafe(deletedImage.created_at),
    deleted_at: deletedImage.deleted_at
      ? toISOStringSafe(deletedImage.deleted_at)
      : null,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardArticleFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleFile";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function postDiscussionBoardMemberArticlesArticleIdFiles(props: {
  member: MemberPayload;
  articleId: string & tags.Format<"uuid">;
  body: IDiscussionBoardArticleFile.ICreate;
}): Promise<IDiscussionBoardArticleFile> {
  const article = await MyGlobal.prisma.discussion_board_articles.findUnique({
    where: {
      id: props.articleId,
    },
    select: {
      id: true,
      discussion_board_member_id: true,
      deleted_at: true,
    },
  });

  if (!article) {
    throw new HttpException("Article not found", 404);
  }

  if (article.deleted_at !== null) {
    throw new HttpException("Article has been deleted", 404);
  }

  if (article.discussion_board_member_id !== props.member.id) {
    throw new HttpException(
      "You can only attach files to your own articles",
      403,
    );
  }

  const fileId = v4() as string & tags.Format<"uuid">;
  const createdAt = toISOStringSafe(new Date());

  const createdFile =
    await MyGlobal.prisma.discussion_board_article_files.create({
      data: {
        id: fileId,
        discussion_board_article_id: props.articleId,
        original_filename: props.body.original_filename,
        file_size: props.body.file_size,
        content_type: props.body.content_type,
        storage_url: props.body.storage_url,
        created_at: createdAt,
      },
    });

  return {
    id: createdFile.id as string & tags.Format<"uuid">,
    discussion_board_article_id:
      createdFile.discussion_board_article_id as string & tags.Format<"uuid">,
    original_filename: createdFile.original_filename,
    file_size: createdFile.file_size,
    content_type: createdFile.content_type,
    storage_url: createdFile.storage_url as string & tags.Format<"uri">,
    created_at: toISOStringSafe(createdFile.created_at),
    deleted_at:
      createdFile.deleted_at === null
        ? undefined
        : toISOStringSafe(createdFile.deleted_at),
  };
}

